#!/usr/bin/env python3
"""
02_parse_documents.py — 解析各类文档格式，提取纯文本和结构化内容
"""
import json
import argparse
import re
from pathlib import Path
from datetime import datetime
import yaml
from rich.console import Console
from rich.progress import track

console = Console()


# ──────────────────────────────────────────────
# 格式解析器
# ──────────────────────────────────────────────

def parse_pdf(path: Path) -> dict:
    """解析 PDF 文件"""
    try:
        import fitz  # pymupdf
        doc = fitz.open(str(path))
        pages = []
        for i, page in enumerate(doc):
            text = page.get_text("text")
            pages.append({"page": i + 1, "text": text.strip()})
        full_text = "\n\n".join(p["text"] for p in pages if p["text"])
        return {
            "full_text": full_text,
            "pages": len(doc),
            "page_texts": pages,
            "method": "pymupdf",
        }
    except ImportError:
        console.print("[yellow]pymupdf 未安装，尝试 pdfplumber...[/yellow]")
        try:
            import pdfplumber
            with pdfplumber.open(str(path)) as pdf:
                pages = []
                for i, page in enumerate(pdf.pages):
                    text = page.extract_text() or ""
                    pages.append({"page": i + 1, "text": text.strip()})
                full_text = "\n\n".join(p["text"] for p in pages)
            return {"full_text": full_text, "pages": len(pages), "page_texts": pages, "method": "pdfplumber"}
        except Exception as e:
            return {"full_text": "", "error": str(e), "method": "failed"}
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_docx(path: Path) -> dict:
    """解析 Word 文档"""
    try:
        from docx import Document
        doc = Document(str(path))
        paragraphs = [p.text.strip() for p in doc.paragraphs if p.text.strip()]

        # 提取表格
        tables = []
        for table in doc.tables:
            rows = []
            for row in table.rows:
                rows.append([cell.text.strip() for cell in row.cells])
            if rows:
                tables.append(rows)

        full_text = "\n".join(paragraphs)
        return {
            "full_text": full_text,
            "paragraphs": paragraphs,
            "tables": tables,
            "method": "python-docx",
        }
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_excel(path: Path) -> dict:
    """解析 Excel 文件"""
    try:
        import pandas as pd
        sheets = {}
        xls = pd.ExcelFile(str(path))
        for sheet_name in xls.sheet_names:
            df = pd.read_excel(str(path), sheet_name=sheet_name)
            # 转为 JSON 序列化格式
            df = df.fillna("").astype(str)
            sheets[sheet_name] = {
                "columns": list(df.columns),
                "rows": df.values.tolist(),
                "row_count": len(df),
            }
        # 生成文字摘要
        summary_parts = []
        for sheet, data in sheets.items():
            cols = "、".join(data["columns"][:10])
            summary_parts.append(
                f"[{sheet}]：{data['row_count']}行，字段：{cols}"
            )
        return {
            "full_text": "\n".join(summary_parts),
            "sheets": sheets,
            "method": "pandas",
        }
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_csv(path: Path) -> dict:
    """解析 CSV 文件"""
    try:
        import pandas as pd
        df = pd.read_csv(str(path), encoding="utf-8", on_bad_lines="skip")
        df = df.fillna("").astype(str)
        summary = f"CSV：{len(df)}行，字段：{'、'.join(list(df.columns)[:10])}"
        return {
            "full_text": summary,
            "columns": list(df.columns),
            "rows": df.values.tolist()[:500],  # 最多500行
            "row_count": len(df),
            "method": "pandas",
        }
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_markdown(path: Path) -> dict:
    """解析 Markdown 文件"""
    try:
        text = path.read_text(encoding="utf-8")
        # 提取章节结构
        sections = []
        current_section = {"heading": "", "content": []}
        for line in text.splitlines():
            if line.startswith("#"):
                if current_section["content"]:
                    sections.append(current_section)
                current_section = {"heading": line.strip(), "content": []}
            else:
                current_section["content"].append(line)
        if current_section["content"]:
            sections.append(current_section)
        return {
            "full_text": text,
            "sections": sections,
            "word_count": len(text.split()),
            "method": "native",
        }
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_json(path: Path) -> dict:
    """解析 JSON 文件"""
    try:
        data = json.loads(path.read_text(encoding="utf-8"))
        # 转为文本摘要
        if isinstance(data, list):
            text = f"JSON 数组：{len(data)}条记录"
            if data:
                text += f"\n样例字段：{', '.join(str(k) for k in data[0].keys() if isinstance(data[0], dict))}"
        elif isinstance(data, dict):
            text = f"JSON 对象，顶层键：{', '.join(list(data.keys())[:10])}"
        else:
            text = str(data)
        return {
            "full_text": text,
            "data": data if isinstance(data, dict) else {"items": data[:100]},
            "method": "native",
        }
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


def parse_text(path: Path) -> dict:
    """解析纯文本文件"""
    try:
        for enc in ["utf-8", "gbk", "latin-1"]:
            try:
                text = path.read_text(encoding=enc)
                return {"full_text": text, "encoding": enc, "method": "native"}
            except UnicodeDecodeError:
                continue
        return {"full_text": "", "error": "编码识别失败", "method": "failed"}
    except Exception as e:
        return {"full_text": "", "error": str(e), "method": "failed"}


PARSERS = {
    "pdf": parse_pdf,
    "docx": parse_docx,
    "doc": parse_docx,
    "xlsx": parse_excel,
    "xls": parse_excel,
    "csv": parse_csv,
    "md": parse_markdown,
    "txt": parse_text,
    "json": parse_json,
    "yaml": parse_text,
    "yml": parse_text,
    "html": parse_text,
    "xml": parse_text,
}


def chunk_text(text: str, max_chars: int = 3000, overlap: int = 200) -> list[str]:
    """将长文本切分为块（按句子边界）"""
    if len(text) <= max_chars:
        return [text]

    # 按段落优先切分
    paragraphs = re.split(r"\n{2,}", text)
    chunks = []
    current_chunk = ""

    for para in paragraphs:
        if len(current_chunk) + len(para) > max_chars:
            if current_chunk:
                chunks.append(current_chunk.strip())
                # 重叠：保留最后 overlap 字符
                current_chunk = current_chunk[-overlap:] + "\n\n" + para
            else:
                # 单段超长，强制切分
                while len(para) > max_chars:
                    chunks.append(para[:max_chars])
                    para = para[max_chars - overlap:]
                current_chunk = para
        else:
            current_chunk += "\n\n" + para

    if current_chunk.strip():
        chunks.append(current_chunk.strip())

    return chunks


def main():
    parser = argparse.ArgumentParser(description="解析文档，提取文本")
    parser.add_argument("--project-dir", "-p", default=".", help="项目根目录")
    parser.add_argument("--max-chars", default=4000, type=int, help="每块最大字符数")
    parser.add_argument("--manifest", default=None, help="文件清单路径")
    args = parser.parse_args()

    project_dir = Path(args.project_dir)
    manifest_path = Path(args.manifest) if args.manifest else (
        project_dir / "extracted" / "file_manifest.json"
    )

    if not manifest_path.exists():
        console.print(f"[red]文件清单不存在：{manifest_path}[/red]")
        console.print("请先运行 01_scan_sources.py")
        return

    manifest = json.loads(manifest_path.read_text(encoding="utf-8"))
    files = [f for f in manifest["files"] if not f["is_duplicate"]]

    console.print(f"[bold cyan]开始解析 {len(files)} 个文件...[/bold cyan]")

    parsed_dir = project_dir / "extracted" / "parsed"
    parsed_dir.mkdir(parents=True, exist_ok=True)

    results = []
    success = error = 0

    for file_info in track(files, description="[cyan]解析中...[/cyan]"):
        file_path = Path(file_info["path"])
        ext = file_info["extension"]

        parser_fn = PARSERS.get(ext, parse_text)
        result = parser_fn(file_path)

        # 切分文本块
        full_text = result.get("full_text", "")
        chunks = chunk_text(full_text, args.max_chars) if full_text else []

        parsed = {
            "source_path": str(file_path),
            "filename": file_info["filename"],
            "extension": ext,
            "hash": file_info["hash"],
            "parsed_at": datetime.now().isoformat(),
            "full_text_length": len(full_text),
            "chunks": chunks,
            "chunk_count": len(chunks),
            "parse_method": result.get("method"),
            "parse_error": result.get("error"),
            "metadata": {
                k: v for k, v in result.items()
                if k not in ("full_text", "method", "error")
                and not isinstance(v, (list, dict)) or k in ("columns",)
            },
        }

        # 保存单文件解析结果
        out_path = parsed_dir / f"{file_info['hash']}.json"
        out_path.write_text(
            json.dumps(parsed, ensure_ascii=False, indent=2),
            encoding="utf-8",
        )

        file_info["parse_status"] = "done" if not result.get("error") else "error"
        file_info["parsed_output"] = str(out_path)
        file_info["chunk_count"] = len(chunks)

        if result.get("error"):
            error += 1
        else:
            success += 1

        results.append(parsed)

    # 更新 manifest
    manifest_path.write_text(
        json.dumps(manifest, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

    # 保存解析摘要
    summary = {
        "parse_time": datetime.now().isoformat(),
        "total": len(files),
        "success": success,
        "error": error,
        "total_chunks": sum(r["chunk_count"] for r in results),
        "avg_chunks_per_file": round(
            sum(r["chunk_count"] for r in results) / max(len(results), 1), 1
        ),
    }
    (project_dir / "extracted" / "parse_summary.json").write_text(
        json.dumps(summary, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

    # 更新 state
    state_path = project_dir / "state.yaml"
    if state_path.exists():
        state = yaml.safe_load(state_path.read_text(encoding="utf-8"))
        state["steps"]["02_parse"] = "done"
        state["stats"]["parsed_files"] = success
        state_path.write_text(yaml.safe_dump(state, allow_unicode=True), encoding="utf-8")

    console.print(f"\n✅ 解析完成：成功 [green]{success}[/green]，失败 [red]{error}[/red]")
    console.print(f"总文本块：[bold]{summary['total_chunks']}[/bold]")
    console.print(f"解析结果目录：[bold green]{parsed_dir}[/bold green]")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
03_extract_entities.py — LLM Schema-Guided 实体与关系抽取
支持 Anthropic Claude / OpenAI / 通义千问
"""
import json
import os
import time
import argparse
from pathlib import Path
from datetime import datetime
import yaml
from rich.console import Console
from rich.progress import track

console = Console()

# ──────────────────────────────────────────────
# 抽取 Prompt 模板
# ──────────────────────────────────────────────

SCHEMA_EXTRACTION_PROMPT = """你是一位企业知识图谱抽取专家。请从以下文档片段中抽取符合给定 Schema 的实体和关系。

## 本体 Schema

### 实体类型（Classes）：
{classes_schema}

### 关系类型（Object Properties）：
{relations_schema}

### 数据属性（Datatype Properties）：
{datatype_props_schema}

## 抽取规则：
1. 只抽取文档中明确出现的信息，不要推测或补充
2. 实体 ID 使用 snake_case 格式，基于实体名称生成
3. 置信度：1.0=明确提及，0.8=可以推断，0.5=不确定，<0.7 进入审核队列
4. 日期统一格式 YYYY-MM-DD，金额统一单位（人民币元）
5. 如果字段信息不清楚，用 null，不要猜测

## 输出格式（严格 JSON，不含 markdown 代码块、不含任何前缀说明）：
{{
  "entities": [
    {{
      "id": "entity_snake_case_id",
      "type": "ClassName",
      "properties": {{
        "property_name": "value"
      }},
      "mention": "文中原始提及文本",
      "confidence": 0.95
    }}
  ],
  "relations": [
    {{
      "type": "property_name",
      "subject_id": "entity_id_1",
      "object_id": "entity_id_2",
      "confidence": 0.9
    }}
  ],
  "extraction_notes": "备注：遇到的不确定情况"
}}

## 文档来源：
文件：{filename}
片段序号：{chunk_index}/{total_chunks}

## 文档内容：
{content}
"""

TBOX_DISCOVERY_PROMPT = """你是一位本体工程专家。请分析以下文档集合的摘要，推断应该构建的 OWL 2 DL 类和关系。

## 文档摘要（来自扫描文档）：
{docs_summary}

## 现有种子类（Seed Classes）：
{seed_classes}

## 任务：
请推断这批文档中出现的核心业务实体类型和它们之间的关系，用于构建企业知识本体。

输出格式（严格 JSON）：
{{
  "discovered_classes": [
    {{
      "name": "ClassName",
      "label_zh": "中文标签",
      "description": "业务定义",
      "superclass": "父类名（可以是 seed_classes 中的类）",
      "example_instances": ["示例1", "示例2"]
    }}
  ],
  "discovered_relations": [
    {{
      "name": "propertyName",
      "label_zh": "中文标签",
      "domain": "主语类",
      "range": "宾语类",
      "is_transitive": false,
      "is_functional": false,
      "description": "描述"
    }}
  ],
  "discovered_datatype_props": [
    {{
      "name": "propertyName",
      "label_zh": "中文标签",
      "domain": "所属类",
      "range": "xsd:string",
      "description": "描述"
    }}
  ]
}}
"""

# ──────────────────────────────────────────────
# LLM 客户端
# ──────────────────────────────────────────────

def call_llm(prompt: str, config: dict) -> str:
    """调用 LLM API"""
    provider = config.get("provider", "anthropic")

    if provider == "anthropic":
        return call_anthropic(prompt, config)
    elif provider == "openai":
        return call_openai(prompt, config)
    else:
        raise ValueError(f"不支持的 LLM 提供商：{provider}")


def call_anthropic(prompt: str, config: dict) -> str:
    """调用 Anthropic Claude API"""
    try:
        import anthropic
        api_key = os.environ.get(config.get("api_key_env", "ANTHROPIC_API_KEY"))
        if not api_key:
            raise ValueError(
                f"环境变量 {config.get('api_key_env', 'ANTHROPIC_API_KEY')} 未设置"
            )
        client = anthropic.Anthropic(api_key=api_key)
        msg = client.messages.create(
            model=config.get("model", "claude-sonnet-4-6"),
            max_tokens=4096,
            messages=[{"role": "user", "content": prompt}],
        )
        return msg.content[0].text
    except ImportError:
        raise ImportError("请安装 anthropic：pip install anthropic --break-system-packages")


def call_openai(prompt: str, config: dict) -> str:
    """调用 OpenAI API"""
    try:
        from openai import OpenAI
        api_key = os.environ.get(config.get("api_key_env", "OPENAI_API_KEY"))
        client = OpenAI(api_key=api_key)
        response = client.chat.completions.create(
            model=config.get("model", "gpt-4o"),
            messages=[{"role": "user", "content": prompt}],
            max_tokens=4096,
        )
        return response.choices[0].message.content
    except ImportError:
        raise ImportError("请安装 openai：pip install openai --break-system-packages")


def safe_parse_json(text: str) -> dict | None:
    """安全解析 LLM 输出的 JSON"""
    # 移除可能的 markdown 代码块
    text = text.strip()
    if text.startswith("```"):
        lines = text.splitlines()
        text = "\n".join(lines[1:-1])
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        # 尝试提取第一个 { } 块
        import re
        match = re.search(r"\{.*\}", text, re.DOTALL)
        if match:
            try:
                return json.loads(match.group())
            except Exception:
                pass
    return None


def build_schema_description(tbox_config: dict) -> tuple[str, str, str]:
    """从 TBox 配置生成 Schema 描述文本"""
    classes = tbox_config.get("classes", [])
    relations = tbox_config.get("relations", [])
    datatype_props = tbox_config.get("datatype_props", [])

    classes_text = "\n".join(
        f"- {c['name']}（{c.get('label_zh', '')}）：{c.get('description', '')}"
        for c in classes
    )
    relations_text = "\n".join(
        f"- {r['name']}（{r.get('label_zh', '')}）：{r.get('domain', '?')} → {r.get('range', '?')}"
        for r in relations
    )
    dtprops_text = "\n".join(
        f"- {d['name']}（{d.get('label_zh', '')}）：{d.get('domain', '?')}.{d['name']} : {d.get('range', 'xsd:string')}"
        for d in datatype_props
    )

    return classes_text, relations_text, dtprops_text


def merge_entities(all_extractions: list[dict]) -> dict:
    """合并多文档抽取结果，去重并解决冲突"""
    entity_map: dict[str, dict] = {}
    all_relations = []

    for extraction in all_extractions:
        if not extraction:
            continue

        for entity in extraction.get("entities", []):
            eid = entity.get("id", "")
            if not eid:
                continue

            if eid not in entity_map:
                entity_map[eid] = entity
            else:
                # 高置信度覆盖低置信度
                if entity.get("confidence", 0) > entity_map[eid].get("confidence", 0):
                    # 合并属性
                    merged_props = {**entity_map[eid].get("properties", {}),
                                    **entity.get("properties", {})}
                    entity_map[eid] = {**entity_map[eid], **entity, "properties": merged_props}

        for rel in extraction.get("relations", []):
            all_relations.append(rel)

    # 去重关系
    seen_rels = set()
    unique_relations = []
    for rel in all_relations:
        key = (rel.get("type"), rel.get("subject_id"), rel.get("object_id"))
        if key not in seen_rels:
            seen_rels.add(key)
            unique_relations.append(rel)

    return {
        "entities": list(entity_map.values()),
        "relations": unique_relations,
    }


def main():
    parser = argparse.ArgumentParser(description="LLM 实体抽取")
    parser.add_argument("--project-dir", "-p", default=".", help="项目根目录")
    parser.add_argument("--api-key", "-k", default=None, help="API Key（可用环境变量替代）")
    parser.add_argument("--tbox-schema", default=None, help="TBox Schema JSON 路径")
    parser.add_argument("--dry-run", action="store_true", help="只显示 Prompt，不实际调用 LLM")
    parser.add_argument("--max-files", type=int, default=None, help="最多处理多少个文件（调试用）")
    args = parser.parse_args()

    project_dir = Path(args.project_dir)

    # 设置 API Key
    if args.api_key:
        os.environ["ANTHROPIC_API_KEY"] = args.api_key

    # 加载配置
    config_path = project_dir / "kb_config.yaml"
    config = {}
    if config_path.exists():
        config = yaml.safe_load(config_path.read_text(encoding="utf-8"))

    llm_config = config.get("llm", {
        "provider": "anthropic",
        "model": "claude-sonnet-4-6",
        "api_key_env": "ANTHROPIC_API_KEY",
        "extraction_confidence_threshold": 0.7,
    })
    confidence_threshold = llm_config.get("extraction_confidence_threshold", 0.7)

    # 加载 TBox Schema
    tbox_schema_path = Path(args.tbox_schema) if args.tbox_schema else (
        project_dir / "extracted" / "tbox_schema.json"
    )

    if tbox_schema_path.exists():
        tbox_config = json.loads(tbox_schema_path.read_text(encoding="utf-8"))
    else:
        # 使用种子类构建基础 Schema
        seed_classes = config.get("ontology", {}).get("seed_classes", [])
        tbox_config = {
            "classes": [
                {"name": c["name"], "label_zh": c.get("label_zh", ""), "description": c.get("description", "")}
                for c in seed_classes
            ],
            "relations": [],
            "datatype_props": [
                {"name": "hasId", "label_zh": "标识符", "domain": "owl:Thing", "range": "xsd:string"},
                {"name": "hasName", "label_zh": "名称", "domain": "owl:Thing", "range": "xsd:string"},
                {"name": "hasDescription", "label_zh": "描述", "domain": "owl:Thing", "range": "xsd:string"},
            ],
        }

    classes_text, relations_text, dtprops_text = build_schema_description(tbox_config)

    # 加载解析结果
    parsed_dir = project_dir / "extracted" / "parsed"
    if not parsed_dir.exists():
        console.print("[red]解析目录不存在，请先运行 02_parse_documents.py[/red]")
        return

    parsed_files = list(parsed_dir.glob("*.json"))
    if args.max_files:
        parsed_files = parsed_files[:args.max_files]

    console.print(f"[bold cyan]开始抽取 {len(parsed_files)} 个文件的实体...[/bold cyan]")

    extract_dir = project_dir / "extracted" / "entities"
    extract_dir.mkdir(parents=True, exist_ok=True)
    review_dir = project_dir / "review_queue"
    review_dir.mkdir(parents=True, exist_ok=True)

    all_extractions = []
    total_entities = 0
    total_relations = 0
    review_count = 0

    for parsed_path in track(parsed_files, description="[cyan]LLM 抽取中...[/cyan]"):
        parsed = json.loads(parsed_path.read_text(encoding="utf-8"))
        chunks = parsed.get("chunks", [])
        filename = parsed.get("filename", "unknown")

        if not chunks:
            continue

        file_extractions = []

        for idx, chunk in enumerate(chunks[:5]):  # 每文件最多处理5块（防止超支）
            if not chunk.strip():
                continue

            prompt = SCHEMA_EXTRACTION_PROMPT.format(
                classes_schema=classes_text,
                relations_schema=relations_text,
                datatype_props_schema=dtprops_text,
                filename=filename,
                chunk_index=idx + 1,
                total_chunks=len(chunks),
                content=chunk[:3000],  # 限制 chunk 长度
            )

            if args.dry_run:
                console.print(f"\n[dim]--- DRY RUN PROMPT ({filename} chunk {idx+1}) ---[/dim]")
                console.print(prompt[:500] + "...")
                continue

            try:
                response_text = call_llm(prompt, llm_config)
                extraction = safe_parse_json(response_text)

                if extraction:
                    extraction["source_file"] = filename
                    extraction["chunk_index"] = idx
                    file_extractions.append(extraction)

                    # 分流：高置信度 vs 审核队列
                    high_conf = {
                        "entities": [
                            e for e in extraction.get("entities", [])
                            if e.get("confidence", 0) >= confidence_threshold
                        ],
                        "relations": [
                            r for r in extraction.get("relations", [])
                            if r.get("confidence", 0) >= confidence_threshold
                        ],
                        "source_file": filename,
                        "chunk_index": idx,
                    }
                    low_conf = {
                        "entities": [
                            e for e in extraction.get("entities", [])
                            if e.get("confidence", 0) < confidence_threshold
                        ],
                        "relations": [
                            r for r in extraction.get("relations", [])
                            if r.get("confidence", 0) < confidence_threshold
                        ],
                        "source_file": filename,
                        "chunk_index": idx,
                    }

                    total_entities += len(high_conf["entities"])
                    total_relations += len(high_conf["relations"])
                    review_count += len(low_conf["entities"])

                    # 保存低置信度到审核队列
                    if low_conf["entities"] or low_conf["relations"]:
                        review_path = review_dir / f"{parsed_path.stem}_chunk{idx}.json"
                        review_path.write_text(
                            json.dumps(low_conf, ensure_ascii=False, indent=2),
                            encoding="utf-8",
                        )

                    all_extractions.append(high_conf)

                # 避免 API 限速
                time.sleep(0.5)

            except Exception as e:
                console.print(f"[red]抽取失败 {filename} chunk{idx}: {e}[/red]")

        # 保存单文件抽取结果
        if file_extractions:
            out_path = extract_dir / f"{parsed_path.stem}_extracted.json"
            out_path.write_text(
                json.dumps(file_extractions, ensure_ascii=False, indent=2),
                encoding="utf-8",
            )

    if args.dry_run:
        console.print("\n[yellow]DRY RUN 模式：未实际调用 LLM[/yellow]")
        return

    # 合并所有抽取结果
    merged = merge_entities(all_extractions)

    merged_path = project_dir / "extracted" / "merged_entities.json"
    merged_path.write_text(
        json.dumps({
            "extracted_at": datetime.now().isoformat(),
            "total_entities": len(merged["entities"]),
            "total_relations": len(merged["relations"]),
            "review_queue_count": review_count,
            **merged,
        }, ensure_ascii=False, indent=2),
        encoding="utf-8",
    )

    # 更新 state
    state_path = project_dir / "state.yaml"
    if state_path.exists():
        state = yaml.safe_load(state_path.read_text(encoding="utf-8"))
        state["steps"]["03_extract"] = "done"
        state["stats"]["extracted_entities"] = len(merged["entities"])
        state_path.write_text(yaml.safe_dump(state, allow_unicode=True), encoding="utf-8")

    console.print(f"\n✅ 抽取完成")
    console.print(f"  实体（高置信度）：[bold green]{total_entities}[/bold green]")
    console.print(f"  关系（高置信度）：[bold green]{total_relations}[/bold green]")
    console.print(f"  需人工审核：[yellow]{review_count}[/yellow]（见 review_queue/）")
    console.print(f"  合并结果：[bold green]{merged_path}[/bold green]")


if __name__ == "__main__":
    main()

#!/usr/bin/env python3
"""
08_query_interface.py — 混合检索 + LLM 问答接口

检索策略（RRF 三路融合）：
  ① SPARQL  — 实体图精确查询（rdflib，无需外部服务）
  ② 向量     — ChromaDB 语义检索
  ③ BM25    — 关键词检索

问答模式：
  --mode cli    交互式命令行（默认）
  --mode batch  批量评估 CQ 覆盖率
  --mode serve  FastAPI HTTP 服务
"""
import json
import pickle
import re
import os
import argparse
from pathlib import Path
from typing import Optional
import yaml
from rich.console import Console
from rich.panel import Panel
from rich.markdown import Markdown

console = Console()


# ── 倒排图索引检索 ──────────────────────────────────────────────

class EntityGraphRetriever:
    def __init__(self, index_path: Path):
        if not index_path.exists():
            self.ready = False
            return
        data = json.loads(index_path.read_text(encoding="utf-8"))
        self.type_index = data.get("type_index", {})
        self.prop_index = data.get("prop_index", {})
        self.rel_index  = data.get("rel_index",  {})
        self.ready      = True

    def search(self, query: str, top_k: int = 10) -> list[dict]:
        if not self.ready:
            return []

        q_lower = query.lower()
        scores: dict[str, float] = {}

        # 属性值匹配
        for key, eids in self.prop_index.items():
            _, val = key.split(":", 1) if ":" in key else ("", key)
            if val and val in q_lower:
                for eid in eids:
                    scores[eid] = scores.get(eid, 0) + 2.0

        # 实体 ID 直接匹配
        for eid in self.rel_index:
            if eid.lower() in q_lower:
                scores[eid] = scores.get(eid, 0) + 5.0

        ranked = sorted(scores.items(), key=lambda x: -x[1])[:top_k]
        results = []
        for eid, score in ranked:
            rels = self.rel_index.get(eid, {})
            results.append({
                "entity_id": eid,
                "score":     score,
                "out_rels":  rels.get("out", [])[:5],
                "in_rels":   rels.get("in",  [])[:5],
                "source":    "entity_graph",
            })
        return results


# ── SPARQL 检索（rdflib）───────────────────────────────────────

class SPARQLRetriever:
    def __init__(self, inferred_graph_path: Path, namespace: str):
        self.ready = False
        self.ns = namespace.rstrip("#") + "#"
        if not inferred_graph_path.exists():
            return
        try:
            from rdflib import Graph
            self.g = Graph()
            self.g.parse(str(inferred_graph_path), format="turtle")
            self.ready = True
            console.print(
                f"[dim]SPARQL 图已加载（{len(self.g)} 三元组）[/dim]"
            )
        except Exception as e:
            console.print(f"[yellow]SPARQL 图加载失败：{e}[/yellow]")

    def query(self, sparql: str) -> list[dict]:
        if not self.ready:
            return []
        try:
            result = self.g.query(sparql)
            rows = []
            for row in result:
                rows.append({str(k): str(v) for k, v in zip(result.vars, row)})
            return rows
        except Exception as e:
            return [{"error": str(e)}]

    def entity_search(self, query_text: str, top_k: int = 8) -> list[dict]:
        """从 SPARQL 图中检索与查询相关的实体"""
        if not self.ready:
            return []
        from rdflib import RDF, OWL, RDFS, Literal
        results = []
        q_lower = query_text.lower()

        # 遍历标签和属性值匹配
        for subj, pred, obj in self.g:
            if isinstance(obj, Literal) and q_lower in str(obj).lower():
                local_s = str(subj).split("#")[-1].split("/")[-1]
                local_p = str(pred).split("#")[-1].split("/")[-1]
                results.append({
                    "entity_id": local_s,
                    "matched_prop": local_p,
                    "matched_val": str(obj)[:200],
                    "score": 3.0,
                    "source": "sparql",
                })
                if len(results) >= top_k * 2:
                    break

        # 去重（按 entity_id）
        seen: set[str] = set()
        unique = []
        for r in results:
            if r["entity_id"] not in seen:
                seen.add(r["entity_id"])
                unique.append(r)
        return unique[:top_k]


# ── 向量检索 ────────────────────────────────────────────────────

class VectorRetriever:
    def __init__(self, chroma_dir: Path, model_name: str):
        self.ready = False
        try:
            import chromadb
            from chromadb.utils import embedding_functions
            ef = embedding_functions.SentenceTransformerEmbeddingFunction(
                model_name=model_name
            )
            client = chromadb.PersistentClient(path=str(chroma_dir))
            self.ent_col   = client.get_collection("kb_entities",   embedding_function=ef)
            self.chunk_col = client.get_collection("kb_chunks",     embedding_function=ef)
            self.ready = True
        except Exception as e:
            console.print(f"[yellow]向量检索不可用：{e}[/yellow]")

    def search(self, query: str, top_k: int = 8) -> list[dict]:
        if not self.ready:
            return []
        results = []
        for col, src in [(self.ent_col, "entity_vector"), (self.chunk_col, "chunk_vector")]:
            try:
                r = col.query(query_texts=[query], n_results=min(top_k, 10))
                for doc, meta, dist in zip(
                    r["documents"][0], r["metadatas"][0], r["distances"][0]
                ):
                    results.append({
                        "text": doc[:500],
                        "meta": meta,
                        "score": 1.0 / (1.0 + dist),  # 距离 → 相似度
                        "source": src,
                    })
            except Exception:
                pass
        return sorted(results, key=lambda x: -x["score"])[:top_k]


# ── BM25 检索 ───────────────────────────────────────────────────

class BM25Retriever:
    def __init__(self, index_path: Path):
        self.ready = False
        if not index_path.exists():
            return
        try:
            with open(index_path, "rb") as f:
                data = pickle.load(f)
            self.bm25         = data["bm25"]
            self.corpus_texts = data["corpus_texts"]
            self.corpus_metas = data["corpus_metas"]
            self.tokenizer    = data.get("tokenizer", "whitespace")
            self.ready        = True
        except Exception as e:
            console.print(f"[yellow]BM25 索引加载失败：{e}[/yellow]")

    def _tokenize(self, text: str) -> list[str]:
        if self.tokenizer == "jieba":
            try:
                import jieba
                return list(jieba.cut_for_search(text.lower()))
            except ImportError:
                pass
        return text.lower().split()

    def search(self, query: str, top_k: int = 8) -> list[dict]:
        if not self.ready:
            return []
        tokens = self._tokenize(query)
        scores = self.bm25.get_scores(tokens)
        top_idx = sorted(range(len(scores)), key=lambda i: -scores[i])[:top_k]
        return [
            {
                "text":  self.corpus_texts[i][:500],
                "meta":  self.corpus_metas[i],
                "score": float(scores[i]),
                "source": "bm25",
            }
            for i in top_idx
            if scores[i] > 0
        ]


# ── RRF 融合 ────────────────────────────────────────────────────

def reciprocal_rank_fusion(
    result_lists: list[list[dict]],
    weights: list[float],
    k: int = 60,
) -> list[dict]:
    """Reciprocal Rank Fusion 多路结果融合"""
    scores: dict[str, float] = {}
    all_items: dict[str, dict] = {}

    for result_list, weight in zip(result_lists, weights):
        for rank, item in enumerate(result_list):
            # 提取去重 key
            key = (
                item.get("entity_id")
                or item.get("text", "")[:80]
                or str(rank)
            )
            rrf_score = weight / (k + rank + 1)
            scores[key] = scores.get(key, 0) + rrf_score
            if key not in all_items:
                all_items[key] = item

    ranked = sorted(scores.items(), key=lambda x: -x[1])
    return [
        {**all_items[key], "rrf_score": score}
        for key, score in ranked
    ]


# ── 上下文组装 ──────────────────────────────────────────────────

def assemble_context(
    fused_results: list[dict],
    entity_graph_path: Path,
    top_k: int = 8,
) -> str:
    """将检索结果组装为 LLM 友好的上下文字符串"""
    parts: list[str] = []

    # 预加载实体图（用于补充实体详情）
    entity_lookup: dict[str, dict] = {}
    if entity_graph_path.exists():
        gd = json.loads(entity_graph_path.read_text(encoding="utf-8"))
        for ent in gd.get("entities", []):
            entity_lookup[ent["id"]] = ent

    seen_ids: set[str] = set()

    for item in fused_results[:top_k]:
        src = item.get("source", "")

        if "entity" in src and "entity_id" in item:
            eid = item["entity_id"]
            if eid in seen_ids:
                continue
            seen_ids.add(eid)

            ent = entity_lookup.get(eid, {})
            types   = ", ".join(ent.get("types", [eid]))
            props   = ent.get("properties", {})
            out_rels = item.get("out_rels", ent.get("out_rels", []))
            in_rels  = item.get("in_rels",  [])

            block = f"【实体】{eid}（{types}）\n"
            if props:
                block += "  属性：\n"
                for k, v in list(props.items())[:8]:
                    block += f"    {k}: {v}\n"
            if out_rels:
                block += "  关系（出）：" + "；".join(
                    f"{r['pred']}→{r['target']}" for r in out_rels[:4]
                ) + "\n"
            if in_rels:
                block += "  关系（入）：" + "；".join(
                    f"{r['source']}→{r['pred']}" for r in in_rels[:4]
                ) + "\n"
            parts.append(block)

        elif "text" in item:
            text = item["text"].strip()
            if not text or text in seen_ids:
                continue
            seen_ids.add(text[:40])
            meta = item.get("meta", {})
            src_file = meta.get("source_file", meta.get("file", "未知来源"))
            parts.append(f"【文档片段｜{src_file}】\n{text}\n")

    return "\n---\n".join(parts) if parts else "（未找到相关内容）"


# ── LLM 问答 ────────────────────────────────────────────────────

QA_SYSTEM_PROMPT = """你是一位企业知识库智能助手。请严格基于提供的知识上下文回答问题。

规则：
1. 只使用上下文中出现的信息作答，不要凭空推测
2. 如果上下文不包含答案，明确说明"知识库中未找到相关信息"
3. 引用具体实体名称或文档来源
4. 回答简洁、结构清晰
5. 如果问题需要推理（如多跳关系），请逐步说明推理路径"""

def ask_llm(question: str, context: str, config: dict) -> str:
    """调用 LLM 生成最终回答"""
    provider = config.get("provider", "anthropic")
    model    = config.get("model", "claude-sonnet-4-6")

    prompt = (
        f"{QA_SYSTEM_PROMPT}\n\n"
        f"## 知识上下文\n{context}\n\n"
        f"## 问题\n{question}\n\n"
        f"## 回答"
    )

    if provider == "anthropic":
        try:
            import anthropic
            api_key = os.environ.get(config.get("api_key_env", "ANTHROPIC_API_KEY"))
            client  = anthropic.Anthropic(api_key=api_key)
            msg     = client.messages.create(
                model=model, max_tokens=2048,
                messages=[{"role": "user", "content": prompt}],
            )
            return msg.content[0].text
        except Exception as e:
            return f"LLM 调用失败：{e}"
    elif provider == "openai":
        try:
            from openai import OpenAI
            api_key = os.environ.get(config.get("api_key_env", "OPENAI_API_KEY"))
            client  = OpenAI(api_key=api_key)
            resp    = client.chat.completions.create(
                model=model, max_tokens=2048,
                messages=[
                    {"role": "system", "content": QA_SYSTEM_PROMPT},
                    {"role": "user",   "content": f"知识上下文：\n{context}\n\n问题：{question}"},
                ],
            )
            return resp.choices[0].message.content
        except Exception as e:
            return f"LLM 调用失败：{e}"
    return "（LLM 不可用，仅返回检索结果）"


# ── 查询引擎 ────────────────────────────────────────────────────

class KBQueryEngine:
    def __init__(self, project_dir: Path, config: dict):
        self.project_dir = project_dir
        self.config      = config
        idx_cfg  = config.get("index",   {})
        llm_cfg  = config.get("llm",     {})
        proj_cfg = config.get("project", {})

        ns      = proj_cfg.get("namespace", "http://corp.example.com/ontology/kb#")
        chroma  = Path(idx_cfg.get("chroma_persist_dir", "./chroma_db"))
        if not chroma.is_absolute():
            chroma = project_dir / chroma
        embed   = idx_cfg.get("embedding_model", "BAAI/bge-m3")

        index_dir = project_dir / "index"

        self.graph_path   = index_dir / "entities_graph.json"
        self.inferred_ttl = index_dir / "inferred_graph.ttl"

        self.sparql  = SPARQLRetriever(self.inferred_ttl, ns)
        self.vector  = VectorRetriever(chroma, embed)
        self.bm25    = BM25Retriever(index_dir / "bm25_index.pkl")
        self.entity  = EntityGraphRetriever(index_dir / "entity_index.json")
        self.llm_cfg = llm_cfg

    def query(
        self,
        question: str,
        top_k: int = 8,
        custom_sparql: Optional[str] = None,
    ) -> dict:
        """执行混合检索并生成回答"""

        # ── 三路检索 ──
        sparql_results = (
            [{"text": str(r), "source": "sparql", "score": 1.0}
             for r in self.sparql.query(custom_sparql)]
            if custom_sparql
            else self.sparql.entity_search(question, top_k)
        )
        vector_results = self.vector.search(question, top_k)
        bm25_results   = self.bm25.search(question, top_k)
        entity_results = self.entity.search(question, top_k)

        # ── RRF 融合 ──
        fused = reciprocal_rank_fusion(
            [sparql_results, vector_results, bm25_results, entity_results],
            weights=[0.40, 0.30, 0.15, 0.15],
        )

        # ── 上下文组装 ──
        context = assemble_context(fused, self.graph_path, top_k)

        # ── LLM 问答 ──
        answer = ask_llm(question, context, self.llm_cfg)

        return {
            "question":       question,
            "answer":         answer,
            "context":        context,
            "sparql_hits":    len(sparql_results),
            "vector_hits":    len(vector_results),
            "bm25_hits":      len(bm25_results),
            "entity_hits":    len(entity_results),
            "fused_results":  len(fused),
        }

    def evaluate_cqs(self, cq_file: Path) -> dict:
        """批量评估 competency_questions.md 的覆盖率"""
        if not cq_file.exists():
            return {"error": "CQ 文件不存在"}

        text = cq_file.read_text(encoding="utf-8")
        cqs  = re.findall(r"- \[.\] (CQ-\d+:.+)", text)
        if not cqs:
            cqs = re.findall(r"[-*] (.+？|.+\?)", text)

        results = []
        answered = 0
        for cq in cqs[:20]:  # 最多评估 20 个 CQ
            r = self.query(cq, top_k=5)
            has_answer = (
                "未找到" not in r["answer"]
                and len(r["answer"]) > 20
                and r["fused_results"] > 0
            )
            answered += int(has_answer)
            results.append({
                "cq": cq,
                "answered": has_answer,
                "answer_preview": r["answer"][:120],
                "hits": r["fused_results"],
            })

        coverage = round(answered / max(len(cqs), 1) * 100, 1)
        return {
            "total_cqs":  len(cqs),
            "answered":   answered,
            "coverage":   f"{coverage}%",
            "details":    results,
        }


# ── CLI 模式 ────────────────────────────────────────────────────

def run_cli(engine: KBQueryEngine):
    console.print(Panel(
        "[bold cyan]企业知识库问答系统[/bold cyan]\n"
        "输入问题开始查询，输入 [yellow]sparql:[/yellow] 前缀执行原始 SPARQL\n"
        "输入 [yellow]exit[/yellow] 退出",
        title="KB Query Interface"
    ))

    while True:
        try:
            question = console.input("\n[bold green]问题> [/bold green]").strip()
        except (EOFError, KeyboardInterrupt):
            break

        if not question or question.lower() in ("exit", "quit", "q"):
            break

        custom_sparql = None
        if question.lower().startswith("sparql:"):
            custom_sparql = question[7:].strip()
            question = f"SPARQL 查询：{custom_sparql}"

        with console.status("[cyan]检索中...[/cyan]"):
            result = engine.query(question, custom_sparql=custom_sparql)

        console.print(Panel(
            Markdown(result["answer"]),
            title="[bold]回答[/bold]",
            border_style="green",
        ))
        console.print(
            f"[dim]来源：SPARQL {result['sparql_hits']} | "
            f"向量 {result['vector_hits']} | "
            f"BM25 {result['bm25_hits']} | "
            f"实体图 {result['entity_hits']}[/dim]"
        )


# ── FastAPI 服务模式 ─────────────────────────────────────────────

def run_server(engine: KBQueryEngine, host: str = "0.0.0.0", port: int = 8765):
    try:
        from fastapi import FastAPI
        from fastapi.middleware.cors import CORSMiddleware
        import uvicorn
        from pydantic import BaseModel
    except ImportError:
        console.print("[red]需要安装：pip install fastapi uvicorn pydantic[/red]")
        return

    app = FastAPI(title="企业知识库 API", version="1.0.0")
    app.add_middleware(
        CORSMiddleware,
        allow_origins=["*"], allow_methods=["*"], allow_headers=["*"],
    )

    class QueryRequest(BaseModel):
        question:      str
        top_k:         int   = 8
        custom_sparql: Optional[str] = None

    @app.post("/query")
    def query(req: QueryRequest):
        return engine.query(req.question, req.top_k, req.custom_sparql)

    @app.get("/evaluate")
    def evaluate():
        cq_path = engine.project_dir / "competency_questions.md"
        return engine.evaluate_cqs(cq_path)

    @app.get("/health")
    def health():
        return {
            "status": "ok",
            "sparql_ready":  engine.sparql.ready,
            "vector_ready":  engine.vector.ready,
            "bm25_ready":    engine.bm25.ready,
            "entity_ready":  engine.entity.ready,
        }

    console.print(f"[bold green]API 服务启动：http://{host}:{port}[/bold green]")
    console.print(f"  POST /query     — 问答查询")
    console.print(f"  GET  /evaluate  — CQ 覆盖率评估")
    console.print(f"  GET  /health    — 健康检查")
    uvicorn.run(app, host=host, port=port)


# ── 主入口 ──────────────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(description="知识库查询接口")
    ap.add_argument("--project-dir", "-p", default=".")
    ap.add_argument("--mode", choices=["cli", "batch", "serve"], default="cli")
    ap.add_argument("--host", default="0.0.0.0")
    ap.add_argument("--port", type=int, default=8765)
    ap.add_argument("--api-key", default=None)
    args = ap.parse_args()

    if args.api_key:
        os.environ["ANTHROPIC_API_KEY"] = args.api_key

    project_dir = Path(args.project_dir)
    config = {}
    cfg_path = project_dir / "kb_config.yaml"
    if cfg_path.exists():
        config = yaml.safe_load(cfg_path.read_text(encoding="utf-8"))

    engine = KBQueryEngine(project_dir, config)

    if args.mode == "cli":
        run_cli(engine)
    elif args.mode == "serve":
        run_server(engine, args.host, args.port)
    elif args.mode == "batch":
        console.print("[cyan]批量评估 CQ 覆盖率...[/cyan]")
        cq_path = project_dir / "competency_questions.md"
        report  = engine.evaluate_cqs(cq_path)

        rpt_path = project_dir / "reports" / "cq_evaluation.json"
        rpt_path.parent.mkdir(parents=True, exist_ok=True)
        rpt_path.write_text(
            json.dumps(report, ensure_ascii=False, indent=2), encoding="utf-8"
        )
        console.print(
            f"\n📊 CQ 覆盖率：[bold green]{report.get('coverage', '—')}[/bold green]"
            f"（{report.get('answered','—')}/{report.get('total_cqs','—')}）"
        )
        console.print(f"报告：[bold]{rpt_path}[/bold]")


if __name__ == "__main__":
    main()

# OWL 2 DL 设计模式库

> 企业知识库常用 OWL 2 DL 建模模式，可直接复用到 TBox 设计中。

---

## 模式 1：枚举状态值（Closed-World Enum）

```turtle
# 用 owl:oneOf 定义封闭枚举个体
kb:OrderStatus
    a owl:Class ;
    owl:equivalentClass [
        owl:oneOf ( kb:Draft kb:Submitted kb:Approved kb:Fulfilled kb:Cancelled )
    ] ;
    rdfs:label "订单状态"@zh .

kb:Draft      a owl:NamedIndividual, kb:OrderStatus ; rdfs:label "草稿"@zh .
kb:Submitted  a owl:NamedIndividual, kb:OrderStatus ; rdfs:label "已提交"@zh .
kb:Approved   a owl:NamedIndividual, kb:OrderStatus ; rdfs:label "已批准"@zh .
kb:Fulfilled  a owl:NamedIndividual, kb:OrderStatus ; rdfs:label "已履行"@zh .
kb:Cancelled  a owl:NamedIndividual, kb:OrderStatus ; rdfs:label "已取消"@zh .

# 使用
kb:order_001 kb:hasStatus kb:Approved .
```

---

## 模式 2：传递性层级（BOM / 组织架构）

```turtle
# 产品 BOM 树（使用传递属性）
kb:hasComponent
    a owl:ObjectProperty, owl:TransitiveProperty ;
    rdfs:domain kb:Product ;
    rdfs:range  kb:Component ;
    rdfs:label  "包含组件（传递）"@zh ;
    rdfs:comment "支持多层嵌套：P→A→B→C 自动推导 P→C"@zh .

# 组织层级（传递 + 不对称）
kb:isSubDepartmentOf
    a owl:ObjectProperty, owl:TransitiveProperty, owl:AsymmetricProperty ;
    rdfs:domain kb:Department ;
    rdfs:range  kb:Department ;
    rdfs:label  "是...的子部门"@zh .

# ⚠️  注意：传递属性不能同时是 FunctionalProperty（违反 OWL 2 DL）
```

---

## 模式 3：等价类定义（Defined Class）

```turtle
# 推理器可从属性值自动分类实例
kb:CriticalSupplier
    a owl:Class ;
    rdfs:subClassOf kb:Supplier ;
    owl:equivalentClass [
        owl:intersectionOf (
            kb:Supplier
            # 风险评分 > 70 由 SWRL/SHACL 处理；
            # OWL DL 中用 hasValue 匹配枚举值更安全
            [ a owl:Restriction ;
              owl:onProperty kb:riskLevel ;
              owl:hasValue kb:High ]
            [ a owl:Restriction ;
              owl:onProperty kb:hasComponent ;
              owl:someValuesFrom [
                  owl:intersectionOf (
                      kb:Component
                      [ a owl:Restriction ;
                        owl:onProperty kb:isSingleSource ;
                        owl:hasValue true ]
                  )
              ]
            ]
        )
    ] ;
    rdfs:label "关键供应商"@zh .
```

---

## 模式 4：属性链（Role Chaining）

```turtle
# 订单 → 供应商：通过零件关联
kb:hasOrderSupplier
    a owl:ObjectProperty ;
    owl:propertyChainAxiom ( kb:hasComponent kb:suppliedBy ) ;
    rdfs:label "订单的零件供应商"@zh ;
    rdfs:comment
        "PurchaseOrder -hasComponent-> Component -suppliedBy-> Supplier
         自动推理：PurchaseOrder -hasOrderSupplier-> Supplier"@zh .

# 上级的上级
kb:hasGrandManager
    a owl:ObjectProperty ;
    owl:propertyChainAxiom ( kb:reportsTo kb:reportsTo ) ;
    rdfs:label "间接上级"@zh .
```

---

## 模式 5：值域约束（Datatype Restrictions）

```turtle
# 数值范围约束
kb:riskScore
    a owl:DatatypeProperty ;
    rdfs:domain kb:Supplier ;
    rdfs:range [
        a rdfs:Datatype ;
        owl:onDatatype xsd:decimal ;
        owl:withRestrictions (
            [ xsd:minInclusive "0.0"^^xsd:decimal ]
            [ xsd:maxInclusive "100.0"^^xsd:decimal ]
        )
    ] .

# 正则格式约束
kb:supplierId
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:range [
        a rdfs:Datatype ;
        owl:onDatatype xsd:string ;
        owl:withRestrictions (
            [ xsd:pattern "^SUP-[0-9]{6}$" ]
        )
    ] .

# 枚举字符串（替代方案，适合不用 oneOf 的场景）
kb:contractType
    a owl:DatatypeProperty ;
    rdfs:range [
        a rdfs:Datatype ;
        owl:onDatatype xsd:string ;
        owl:withRestrictions (
            [ xsd:pattern "^(Framework|Spot|Long-term)$" ]
        )
    ] .
```

---

## 模式 6：基数约束（Qualified Cardinality）

```turtle
# 精确 1 个（替代 FunctionalProperty，更灵活）
kb:PurchaseOrder
    a owl:Class ;
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty kb:suppliedBy ;
        owl:qualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass kb:Supplier
    ] ;
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty kb:hasComponent ;
        owl:minQualifiedCardinality "1"^^xsd:nonNegativeInteger ;
        owl:onClass kb:Component
    ] .

# 最多 2 个审批人
kb:HighValueOrder
    a owl:Class ;
    rdfs:subClassOf [
        a owl:Restriction ;
        owl:onProperty kb:approvedBy ;
        owl:maxQualifiedCardinality "2"^^xsd:nonNegativeInteger ;
        owl:onClass kb:Employee
    ] .
```

---

## 模式 7：N 元关系（N-ary Relationship）

当关系本身需要附带属性时（如"价格为X时从供应商Y采购Z"）：

```turtle
# 将关系具化为类
kb:SupplyAgreement
    a owl:Class ;
    rdfs:label "供货协议"@zh ;
    rdfs:comment "N元关系：Supplier + Component + PriceCondition"@zh .

kb:agreementSupplier
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain kb:SupplyAgreement ;
    rdfs:range  kb:Supplier .

kb:agreementComponent
    a owl:ObjectProperty, owl:FunctionalProperty ;
    rdfs:domain kb:SupplyAgreement ;
    rdfs:range  kb:Component .

kb:agreedUnitPrice
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain kb:SupplyAgreement ;
    rdfs:range  xsd:decimal .

# 实例化
kb:agreement_001
    a kb:SupplyAgreement ;
    kb:agreementSupplier  kb:supplier_acme ;
    kb:agreementComponent kb:component_steel_001 ;
    kb:agreedUnitPrice    "125.50"^^xsd:decimal .
```

---

## 模式 8：版本化实体（Temporal Ontology）

```turtle
# 为需要历史版本的实体添加时间戳
kb:VersionedEntity
    a owl:Class ;
    rdfs:label "版本化实体"@zh .

kb:validFrom
    a owl:DatatypeProperty ;
    rdfs:domain kb:VersionedEntity ;
    rdfs:range  xsd:dateTime ;
    rdfs:label  "生效时间"@zh .

kb:validTo
    a owl:DatatypeProperty ;
    rdfs:domain kb:VersionedEntity ;
    rdfs:range  xsd:dateTime ;
    rdfs:label  "失效时间"@zh .

kb:replacedBy
    a owl:ObjectProperty ;
    rdfs:domain kb:VersionedEntity ;
    rdfs:range  kb:VersionedEntity ;
    rdfs:label  "被...替代"@zh .

kb:isCurrentVersion
    a owl:DatatypeProperty, owl:FunctionalProperty ;
    rdfs:domain kb:VersionedEntity ;
    rdfs:range  xsd:boolean ;
    rdfs:label  "是否当前版本"@zh .
```

