```turtle
# 将不同数据源的同一实体对齐
kb:supplier_acme_erp
    owl:sameAs kb:supplier_acme_crm ;
    owl:sameAs <http://dbpedia.org/resource/Acme_Corporation> .

# 批量对齐规则（SPARQL Update）
