## 快速检查清单：OWL 2 DL 合规性

```
✅ 类 IRI ≠ 属性 IRI（不同命名）
✅ owl:ObjectProperty 与 owl:DatatypeProperty 使用不同 IRI
✅ 传递属性（TransitiveProperty）≠ 同时 FunctionalProperty
✅ 属性链（propertyChainAxiom）无循环
✅ owl:oneOf 仅在 TBox 类公理中使用
✅ 具名图（NamedGraph）不嵌套 owl:Ontology 声明
✅ 所有限制（Restriction）使用空白节点，不使用具名 IRI
✅ 每个类和属性都有 rdfs:label + rdfs:comment
```

# SPARQL 查询模板库

> 企业知识库常用 SPARQL 查询，配合 rdflib 或 Apache Jena Fuseki 使用。  
> 前缀声明：所有模板均假设已声明以下前缀。

```sparql
PREFIX kb:   <http://corp.example.com/ontology/kb#>
PREFIX owl:  <http://www.w3.org/2002/07/owl#>
PREFIX rdf:  <http://www.w3.org/1999/02/22-rdf-syntax-ns#>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>
PREFIX xsd:  <http://www.w3.org/2001/XMLSchema#>
```

---

## ① 基础实体查询

### 查询某类型的所有实体

```sparql
SELECT ?entity ?name ?id WHERE {
    ?entity a kb:Supplier ;
            kb:hasName ?name ;
            kb:hasId   ?id .
}
ORDER BY ?name
LIMIT 100
```

### 按属性值过滤

```sparql
# 查询风险评分 > 70 的供应商
SELECT ?supplier ?name ?score WHERE {
    ?supplier a kb:Supplier ;
              kb:hasName  ?name ;
              kb:riskScore ?score .
    FILTER (?score > 70.0)
}
ORDER BY DESC(?score)
```

### 全文搜索（CONTAINS + LCASE）

```sparql
SELECT ?entity ?type ?name WHERE {
    ?entity a ?type ;
            kb:hasName ?name .
    FILTER CONTAINS(LCASE(?name), "acme")
    FILTER (?type != owl:NamedIndividual)
}
```

---

## ② 关系查询

### 单跳：查询某实体的直接关联

```sparql
# 查询订单 PO-001 的所有关联实体
SELECT ?predicate ?related ?relatedName WHERE {
    ?order kb:hasId "PO-001"^^xsd:string .
    ?order ?predicate ?related .
    OPTIONAL { ?related kb:hasName ?relatedName }
    FILTER (?predicate != rdf:type && ?predicate != rdfs:label)
}
```

### 多跳：利用传递属性（推理后才有效）

```sparql
# 产品的完整 BOM（包含所有层级子部件）
# 需要先运行推理器展开 TransitiveProperty
SELECT ?product ?component ?componentName WHERE {
    ?product kb:hasId "PROD-001"^^xsd:string ;
             kb:hasComponent ?component .  # 推理后包含所有层级
    ?component kb:hasName ?componentName .
}
ORDER BY ?componentName
```

### 反向查询

```sparql
# 谁使用了零件 COMP-001？
SELECT ?product ?productName WHERE {
    ?component kb:hasId "COMP-001"^^xsd:string .
    ?product kb:hasComponent ?component ;
             kb:hasName ?productName .
}
```

---

## ③ 聚合统计

### 分组计数

```sparql
# 每个供应商的订单数
SELECT ?supplierName (COUNT(?order) AS ?orderCount) WHERE {
    ?supplier a kb:Supplier ;
              kb:hasName ?supplierName .
    ?order a kb:PurchaseOrder ;
           kb:suppliedBy ?supplier .
}
GROUP BY ?supplierName
ORDER BY DESC(?orderCount)
LIMIT 20
```

### 求和 + 过滤聚合结果

```sparql
# 订单总额 > 100万 的供应商
SELECT ?supplierName (SUM(?amount) AS ?totalAmount) WHERE {
    ?supplier a kb:Supplier ;
              kb:hasName ?supplierName .
    ?order a kb:PurchaseOrder ;
           kb:suppliedBy ?supplier ;
           kb:totalAmount ?amount .
}
GROUP BY ?supplierName
HAVING (SUM(?amount) > 1000000)
ORDER BY DESC(?totalAmount)
```

---

## ④ 推理查询

### 检查实例是否属于推理类

```sparql
# 推理后：哪些供应商是 CriticalSupplier（等价类推理）
SELECT ?supplier ?name WHERE {
    ?supplier a kb:CriticalSupplier ;  # 可能是推理得出
              kb:hasName ?name .
}
```

### 属性链推理

```sparql
# 订单的零件供应商（通过属性链推理）
SELECT ?order ?orderId ?supplier ?supplierName WHERE {
    ?order a kb:PurchaseOrder ;
           kb:hasId ?orderId ;
           kb:hasOrderSupplier ?supplier .  # 属性链推理结果
    ?supplier kb:hasName ?supplierName .
}
```

---

## ⑤ 时间窗口查询

```sparql
# 30天内到期的合同
SELECT ?contract ?contractId ?endDate WHERE {
    ?contract a kb:Contract ;
              kb:hasId ?contractId ;
              kb:validTo ?endDate .
    FILTER (
        ?endDate >= NOW() &&
        ?endDate <= NOW() + "P30D"^^xsd:duration
    )
}
ORDER BY ?endDate
```

---

## ⑥ SPARQL Update（数据修改）

### 批量插入三元组

```sparql
INSERT DATA {
    kb:supplier_new001
        a owl:NamedIndividual , kb:Supplier ;
        kb:hasId      "SUP-000042"^^xsd:string ;
        kb:hasName    "新供应商 XYZ"^^xsd:string ;
        kb:riskScore  "35.0"^^xsd:decimal .
}
```

### 版本迁移（属性重命名）

```sparql
DELETE { ?s kb:vendorScore ?o }
INSERT { ?s kb:riskScore   ?o }
WHERE  { ?s kb:vendorScore ?o }
```

### owl:sameAs 批量对齐

```sparql
INSERT { ?s owl:sameAs ?t }
WHERE {
    ?s a kb:Supplier ; kb:hasId ?id .
    ?t a kb:Vendor   ; kb:taxCode ?id .
    FILTER (?s != ?t)
}
```

---

## ⑦ 图谱探索查询

### 本体类层级

```sparql
SELECT ?class ?superClass ?label WHERE {
    ?class a owl:Class ;
           rdfs:label ?label .
    OPTIONAL { ?class rdfs:subClassOf ?superClass }
    FILTER (LANG(?label) = "zh")
}
ORDER BY ?superClass ?class
```

### 属性清单

```sparql
SELECT ?prop ?type ?domain ?range ?label WHERE {
    ?prop a ?type ;
          rdfs:label ?label .
    OPTIONAL { ?prop rdfs:domain ?domain }
    OPTIONAL { ?prop rdfs:range  ?range  }
    FILTER (?type IN (owl:ObjectProperty, owl:DatatypeProperty))
    FILTER (LANG(?label) = "zh")
}
ORDER BY ?type ?prop
```

### 孤岛实体检测（无任何关联）

```sparql
SELECT ?entity ?name WHERE {
    ?entity a owl:NamedIndividual ;
            kb:hasName ?name .
    FILTER NOT EXISTS {
        { ?entity ?p ?o . FILTER (?p != rdf:type && ?p != rdfs:label) }
        UNION
        { ?s ?p ?entity . FILTER (?p != rdf:type) }
    }
}
```

---

## rdflib Python 使用示例

```python
from rdflib import Graph, Namespace
import owlrl

KB = Namespace("http://corp.example.com/ontology/kb#")

g = Graph()
g.parse("ontology/tbox_v1.0.0.ttl", format="turtle")
g.parse("abox/abox_v1.0.0.ttl",      format="turtle")

# 运行推理
owlrl.DeductiveClosure(owlrl.OWLRL_Semantics).expand(g)

# 执行查询
qres = g.query("""
    PREFIX kb: <http://corp.example.com/ontology/kb#>
    SELECT ?name ?score WHERE {
        ?s a kb:CriticalSupplier ;
           kb:hasName  ?name ;
           kb:riskScore ?score .
    }
    ORDER BY DESC(?score)
""")

for row in qres:
    print(f"{row.name}  风险评分：{row.score}")
```

@prefix sh:    <http://www.w3.org/ns/shacl#> .
@prefix owl:   <http://www.w3.org/2002/07/owl#> .
@prefix rdf:   <http://www.w3.org/1999/02/22-rdf-syntax-ns#> .
@prefix rdfs:  <http://www.w3.org/2000/01/rdf-schema#> .
@prefix xsd:   <http://www.w3.org/2001/XMLSchema#> .
@prefix kb:    <http://corp.example.com/ontology/kb#> .

# ================================================================
# SHACL 数据质量约束 — 企业知识库
# 使用方式：pyshacl -s shacl_shapes.ttl -d your_abox.ttl
# ================================================================

# ── 通用实体约束 ──────────────────────────────────────────────

kb:NamedIndividualShape
    a sh:NodeShape ;
    sh:targetClass owl:NamedIndividual ;

    sh:property [
        sh:path kb:hasId ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:message "每个实体必须有且仅有一个 hasId"@zh
    ] ;

    sh:property [
        sh:path kb:hasName ;
        sh:minCount 1 ;
        sh:datatype xsd:string ;
        sh:message "每个实体必须有名称"@zh
    ] ;

    sh:property [
        sh:path kb:extractionConfidence ;
        sh:datatype xsd:decimal ;
        sh:minInclusive 0.0 ;
        sh:maxInclusive 1.0 ;
        sh:message "抽取置信度必须在 0.0~1.0 之间"@zh
    ] .

# ── 供应商约束 ──────────────────────────────────────────────

kb:SupplierShape
    a sh:NodeShape ;
    sh:targetClass kb:Supplier ;

    sh:property [
        sh:path kb:hasId ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:pattern "^SUP-[0-9A-Z]{4,10}$" ;
        sh:message "供应商编号格式：SUP-XXXX（字母数字）"@zh
    ] ;

    sh:property [
        sh:path kb:hasName ;
        sh:minCount 1 ;
        sh:maxCount 1 ;
        sh:datatype xsd:string ;
        sh:minLength 2 ;
        sh:maxLength 200 ;
        sh:message "供应商名称长度 2~200 字符"@zh
    ] ;

    sh:property [
        sh:path kb:country ;
        sh:datatype xsd:string ;
        sh:pattern "^[A-Z]{2}$" ;
        sh:message "国家代码必须是 ISO 3166-1 Alpha-2 两位大写字母"@zh
    ] ;

    sh:property [
        sh:path kb:riskScore ;
        sh:datatype xsd:decimal ;
        sh:minInclusive 0.0 ;
        sh:maxInclusive 100.0 ;
        sh:message "风险评分范围 0.0~100.0"@zh
