"""
Self-review audit: static analysis of all scripts
Checks: imports, error handling, OWL DL compliance, missing features, API surface
"""
import ast, re
from pathlib import Path

issues = {}
SCRIPTS = sorted(Path("scripts").glob("*.py"))

for script in SCRIPTS:
    src = script.read_text()
    name = script.name
    bugs = []

    # 1. check for bare except
    if "except:" in src and "except Exception" not in src.split("except:")[0][-5:]:
        bugs.append("bare `except:` without exception type")

    # 2. check try/except around file I/O
    if ".read_text(" in src and "try:" not in src:
        bugs.append("file I/O without try/except wrapper")

    # 3. check for hardcoded API keys
    if re.search(r"sk-ant-|sk-[A-Za-z0-9]{48}", src):
        bugs.append("HARDCODED API KEY FOUND")

    # 4. check for missing __main__ guard  
    if "def main(" in src and 'if __name__ == "__main__"' not in src:
        bugs.append("main() without __main__ guard")

    # 5. missing logging (uses print instead of loguru/logging)
    print_count = src.count("print(")
    if print_count > 10:
        bugs.append(f"uses print() x{print_count} — no structured logging")

    # 6. check for missing type hints on functions
    tree = ast.parse(src)
    funcs = [n for n in ast.walk(tree) if isinstance(n, ast.FunctionDef)]
    untyped = [f.name for f in funcs if not f.returns and not f.name.startswith("_")]
    if len(untyped) > 3:
        bugs.append(f"untyped functions: {untyped[:4]}...")

    # 7. check OWL DL pitfall: FunctionalProperty + TransitiveProperty
    if "FunctionalProperty" in src and "TransitiveProperty" in src:
        # check if the validation code exists
        if "FORBIDDEN_COMBOS" not in src and "_validate_property" not in src:
            bugs.append("OWL DL RISK: Func+Trans combo possible, no guard")

    # 8. check for config loading — is it resilient?
    if "yaml.safe_load" in src and "except" not in src:
        bugs.append("yaml.safe_load without error handling")

    # 9. check for missing incremental / resume support
    if name in ("03_extract_entities.py", "02_parse_documents.py"):
        if "already_processed" not in src and "skip" not in src.lower():
            bugs.append("no resume/skip for already-processed files (expensive re-runs)")

    # 10. check ABox for PII guard
    if name == "05_populate_abox.py":
        if "PII" not in src and "personal" not in src.lower():
            bugs.append("no PII scrubbing / redaction layer")

    # 11. check query interface for streaming
    if name == "08_query_interface.py":
        if "stream" not in src.lower():
            bugs.append("LLM answers non-streaming (bad UX for long responses)")
        if "cache" not in src.lower():
            bugs.append("no query result caching (repeated identical queries hit LLM every time)")
        if "history" not in src.lower():
            bugs.append("CLI has no conversation history / follow-up support")

    # 12. check 07 for missing cosine similarity fallback
    if name == "07_build_index.py":
        if "cosine" not in src.lower() and "distance" not in src.lower():
            bugs.append("ChromaDB distance metric not explicitly set (defaults may vary)")

    issues[name] = bugs

print("╔══════════════════════════════════════════════════════════╗")
print("║           SELF-REVIEW AUDIT REPORT                      ║")
print("╚══════════════════════════════════════════════════════════╝\n")

total = 0
for name, bugs in issues.items():
    mark = "✅" if not bugs else "⚠️ "
    print(f"{mark} {name}")
    for b in bugs:
        print(f"     → {b}")
        total += 1
    if not bugs:
        print("     (no issues)")

print(f"\n{'─'*60}")
print(f"Total issues: {total} across {len(SCRIPTS)} scripts")
AUDIT

