#!/usr/bin/env python3
"""
03_extract_entities.py — LLM Schema-Guided 实体抽取 v2

v2 改进：
  - NEW: 断点续传（已处理文件自动跳过）
  - NEW: ODKE+ 风格"本体片段"提示词（每次只发送相关类子集，减少 token）
  - NEW: 两步式 Schema 发现（Feng et al. 2024）：先从文本推断类，再抽取
  - NEW: 抽取结果 JSON 序列化验证（防止解析错误静默丢失）
  - NEW: 速率限制退避（指数退避重试）
  - FIX: 置信度 None 值安全处理
"""
import json
import os
import re
import time
import argparse
from pathlib import Path
from datetime import datetime
import yaml
from rich.console import Console
from rich.progress import track

console = Console()

# ── Prompt 模板 ──────────────────────────────────────────────────

SCHEMA_EXTRACTION_PROMPT = """\
你是企业知识图谱专家。从文档片段中抽取符合给定本体 Schema 的实体和关系。

## 本体 Schema（仅抽取以下类型）

### 实体类（只抽取文中出现的）：
{classes_schema}

### 关系类型：
{relations_schema}

## 规则
1. 只抽取文中明确出现的信息，不推测
2. 实体 ID：英文 snake_case，基于实体名（全局唯一）
3. 置信度：1.0=明确，0.8=可推断，0.5=不确定
4. 日期格式：YYYY-MM-DD；金额：数字（人民币元）
5. 字段不清楚用 null，不猜测

## 输出（严格 JSON，无 markdown 代码块，无前缀说明）
{{"entities":[{{"id":"entity_snake_id","type":"ClassName","properties":{{"prop":"val"}},"mention":"原文","confidence":0.95}}],"relations":[{{"type":"propertyName","subject_id":"id1","object_id":"id2","confidence":0.9}}],"extraction_notes":"备注"}}

## 文档 [{filename}  片段 {chunk_index}/{total_chunks}]
{content}
"""

ONTOLOGY_SNIPPET_PROMPT = """\
给定以下文档片段，判断其中涉及哪些实体类型，从候选列表中选择最相关的子集（不超过5个）。

候选类型：{all_classes}

文档片段（前500字）：
{content_preview}

输出 JSON 数组，仅包含相关类型名（如 ["Supplier", "Contract"]，无其他内容）：
"""

# ── LLM 调用 ────────────────────────────────────────────────────

def call_llm(prompt: str, config: dict, max_retries: int = 3) -> str | None:
    provider = config.get("provider", "anthropic")
    model    = config.get("model",    "claude-sonnet-4-6")

    for attempt in range(max_retries):
        try:
            if provider == "anthropic":
                import anthropic
                api_key = os.environ.get(config.get("api_key_env","ANTHROPIC_API_KEY"))
                if not api_key:
                    raise ValueError(f"环境变量 {config.get('api_key_env','ANTHROPIC_API_KEY')} 未设置")
                client = anthropic.Anthropic(api_key=api_key)
                msg    = client.messages.create(
                    model=model, max_tokens=4096,
                    messages=[{"role":"user","content":prompt}],
                )
                return msg.content[0].text
            elif provider == "openai":
                from openai import OpenAI
                api_key = os.environ.get(config.get("api_key_env","OPENAI_API_KEY"))
                client  = OpenAI(api_key=api_key)
                resp    = client.chat.completions.create(
                    model=model, max_tokens=4096,
                    messages=[{"role":"user","content":prompt}],
                )
                return resp.choices[0].message.content
        except Exception as e:
            wait = 2 ** attempt
            console.print(f"[yellow]LLM 调用失败（尝试 {attempt+1}/{max_retries}）：{e} | 等待 {wait}s[/yellow]")
            if attempt < max_retries - 1:
                time.sleep(wait)
    return None


def safe_parse_json(text: str) -> dict | None:
    if not text:
        return None
    text = text.strip()
    if text.startswith("```"):
        text = "\n".join(text.splitlines()[1:-1])
    try:
        return json.loads(text)
    except json.JSONDecodeError:
        m = re.search(r"\{.*\}", text, re.DOTALL)
        if m:
            try:
                return json.loads(m.group())
            except Exception:
                pass
    return None


# ── ODKE+ 本体片段选择 ───────────────────────────────────────────

def select_relevant_classes(
    chunk: str,
    all_classes: list[dict],
    config: dict,
) -> list[dict]:
    """
    从全量 Schema 中为当前文档片段选择最相关的类子集（ODKE+ 思路）。
    若 LLM 调用失败，退化到全量 Schema。
    """
    if len(all_classes) <= 5:
        return all_classes  # 类少时不需要筛选

    class_names = [c["name"] for c in all_classes]
    prompt = ONTOLOGY_SNIPPET_PROMPT.format(
        all_classes=", ".join(class_names),
        content_preview=chunk[:500],
    )
    text = call_llm(prompt, config)
    if not text:
        return all_classes

    try:
        text = text.strip()
        if text.startswith("```"):
            text = "\n".join(text.splitlines()[1:-1])
        selected = json.loads(text)
        if isinstance(selected, list) and selected:
            name_set = set(selected)
            filtered = [c for c in all_classes if c["name"] in name_set]
            return filtered if filtered else all_classes
    except Exception:
        pass
    return all_classes


# ── Schema 文本序列化 ────────────────────────────────────────────

def schema_to_text(classes: list[dict], relations: list[dict]) -> tuple[str, str]:
    cls_text = "\n".join(
        f"- {c['name']}（{c.get('label_zh','')}）：{c.get('description','')}  "
        f"[属性: {', '.join(p.get('name','') for p in [] if True)}]"
        for c in classes
    )
    rel_text = "\n".join(
        f"- {r['name']}：{r.get('domain','?')} → {r.get('range','?')}  {r.get('description','')}"
        for r in relations
    )
    return cls_text or "（无类定义）", rel_text or "（无关系定义）"


# ── 实体合并 ────────────────────────────────────────────────────

def merge_entities(all_extractions: list[dict]) -> dict:
    entity_map: dict[str, dict] = {}
    all_relations: list[dict]   = []

    for extraction in all_extractions:
        if not extraction:
            continue
        for entity in extraction.get("entities", []):
            eid  = entity.get("id", "")
            conf = entity.get("confidence") or 0.0
            if not eid:
                continue
            if eid not in entity_map:
                entity_map[eid] = entity
            elif conf > (entity_map[eid].get("confidence") or 0.0):
                merged_props = {
                    **entity_map[eid].get("properties", {}),
                    **entity.get("properties", {}),
                }
                entity_map[eid] = {**entity_map[eid], **entity, "properties": merged_props}

        for rel in extraction.get("relations", []):
            all_relations.append(rel)

    # Deduplicate relations
    seen: set[tuple] = set()
    unique_rels: list[dict] = []
    for rel in all_relations:
        key = (rel.get("type"), rel.get("subject_id"), rel.get("object_id"))
        if key not in seen:
            seen.add(key)
            unique_rels.append(rel)

    return {"entities": list(entity_map.values()), "relations": unique_rels}


# ── 主入口 ──────────────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(description="LLM 实体抽取 v2")
    ap.add_argument("--project-dir", "-p", default=".")
    ap.add_argument("--api-key",     "-k", default=None)
    ap.add_argument("--tbox-schema", default=None)
    ap.add_argument("--dry-run",     action="store_true")
    ap.add_argument("--max-files",   type=int, default=None)
    ap.add_argument("--max-chunks",  type=int, default=5,
                    help="每文件最大处理块数（默认5，减少成本）")
    ap.add_argument("--resume",      action="store_true", default=True,
                    help="跳过已处理文件（断点续传，默认开启）")
    ap.add_argument("--no-resume",   action="store_true",
                    help="强制重新处理所有文件")
    ap.add_argument("--odke",        action="store_true", default=True,
                    help="启用 ODKE+ 本体片段动态选择（默认开启）")
    args = ap.parse_args()

    if args.api_key:
        os.environ["ANTHROPIC_API_KEY"] = args.api_key

    project_dir = Path(args.project_dir)
    config      = {}
    cfg_path    = project_dir / "kb_config.yaml"
    if cfg_path.exists():
        try:
            config = yaml.safe_load(cfg_path.read_text(encoding="utf-8"))
        except Exception as e:
            console.print(f"[yellow]配置读取失败：{e}[/yellow]")

    llm_config = config.get("llm", {
        "provider": "anthropic", "model": "claude-sonnet-4-6",
        "api_key_env": "ANTHROPIC_API_KEY",
        "extraction_confidence_threshold": 0.7,
    })
    threshold = llm_config.get("extraction_confidence_threshold", 0.7)

    # Schema 加载
    schema_path = (
        Path(args.tbox_schema) if args.tbox_schema
        else project_dir / "extracted" / "tbox_schema.json"
    )
    if schema_path.exists():
        try:
            tbox = json.loads(schema_path.read_text(encoding="utf-8"))
        except Exception:
            tbox = {}
    else:
        seed = config.get("ontology", {}).get("seed_classes", [])
        tbox = {"classes": seed, "relations": [], "datatype_props": []}

    all_classes  = tbox.get("classes",   [])
    all_relations = tbox.get("relations", [])

    # 解析文件目录
    parsed_dir = project_dir / "extracted" / "parsed"
    if not parsed_dir.exists():
        console.print("[red]parsed/ 不存在，请先运行 02_parse_documents.py[/red]")
        return

    parsed_files = list(parsed_dir.glob("*.json"))
    if args.max_files:
        parsed_files = parsed_files[:args.max_files]

    extract_dir = project_dir / "extracted" / "entities"
    review_dir  = project_dir / "review_queue"
    extract_dir.mkdir(parents=True, exist_ok=True)
    review_dir.mkdir(parents=True, exist_ok=True)

    # 断点续传：确定已处理文件集合
    use_resume = args.resume and not args.no_resume
    already_done: set[str] = set()
    if use_resume:
        already_done = {f.stem.replace("_extracted", "") for f in extract_dir.glob("*_extracted.json")}
        if already_done:
            console.print(f"[dim]断点续传：跳过 {len(already_done)} 个已处理文件[/dim]")

    console.print(f"[bold cyan]实体抽取：{len(parsed_files)} 文件  threshold={threshold}  odke={not args.dry_run and args.odke}[/bold cyan]")

    all_extractions: list[dict] = []
    total_ent = total_rel = review_count = skipped = 0

    for pf in track(parsed_files, description="[cyan]LLM 抽取...[/cyan]"):
        stem = pf.stem

        # 断点续传跳过
        if use_resume and stem in already_done:
            skipped += 1
            # Load existing to include in merge
            ep = extract_dir / f"{stem}_extracted.json"
            if ep.exists():
                try:
                    for ex in json.loads(ep.read_text(encoding="utf-8")):
                        all_extractions.append(ex)
                except Exception:
                    pass
            continue

        try:
            parsed = json.loads(pf.read_text(encoding="utf-8"))
        except Exception as e:
            console.print(f"[yellow]读取 {pf.name} 失败：{e}[/yellow]")
            continue

        chunks   = parsed.get("chunks", [])
        filename = parsed.get("filename", "unknown")
        if not chunks:
            continue

        file_extractions: list[dict] = []

        for idx, chunk in enumerate(chunks[:args.max_chunks]):
            if not chunk.strip():
                continue

            # ODKE+ 本体片段动态选择
            if args.odke and not args.dry_run and len(all_classes) > 5:
                relevant_classes = select_relevant_classes(chunk, all_classes, llm_config)
            else:
                relevant_classes = all_classes

            cls_text, rel_text = schema_to_text(relevant_classes, all_relations)

            prompt = SCHEMA_EXTRACTION_PROMPT.format(
                classes_schema=cls_text,
                relations_schema=rel_text,
                filename=filename,
                chunk_index=idx + 1,
                total_chunks=len(chunks),
                content=chunk[:3000],
            )

            if args.dry_run:
                console.print(f"[dim]DRY RUN [{filename} chunk{idx+1}] prompt={len(prompt)} chars[/dim]")
                continue

            response = call_llm(prompt, llm_config)
            if not response:
                continue

            extraction = safe_parse_json(response)
            if not extraction:
                console.print(f"[yellow]JSON 解析失败：{filename} chunk{idx+1}[/yellow]")
                continue

            extraction["source_file"] = filename
            extraction["chunk_index"] = idx
            file_extractions.append(extraction)

            # 置信度分流
            high = {
                "entities":  [e for e in extraction.get("entities", [])
                              if (e.get("confidence") or 0) >= threshold],
                "relations": [r for r in extraction.get("relations", [])
                              if (r.get("confidence") or 0) >= threshold],
                "source_file": filename, "chunk_index": idx,
            }
            low = {
                "entities":  [e for e in extraction.get("entities", [])
                              if (e.get("confidence") or 0) < threshold],
                "relations": [r for r in extraction.get("relations", [])
                              if (r.get("confidence") or 0) < threshold],
                "source_file": filename, "chunk_index": idx,
            }

            total_ent += len(high["entities"])
            total_rel += len(high["relations"])
            review_count += len(low["entities"])

            if low["entities"] or low["relations"]:
                rp = review_dir / f"{stem}_chunk{idx}.json"
