#!/usr/bin/env python3
"""
08_query_interface.py — 混合检索 + LLM 问答 v2

v2 改进：
  - NEW: LLM 回答流式输出（Anthropic streaming）
  - NEW: 查询结果 LRU 缓存（相同问题不重复打 LLM）
  - NEW: CLI 多轮对话历史（支持 follow-up 追问）
  - NEW: ChromaDB 距离度量明确设置为 cosine
  - NEW: /help 命令、/clear 清空历史、/eval 触发 CQ 评估
  - FIX: EntityGraphRetriever property value 匹配更健壮
"""
import json
import pickle
import re
import os
import argparse
import functools
from pathlib import Path
from typing import Optional
import yaml
from rich.console import Console
from rich.panel import Panel
from rich.markdown import Markdown

console = Console()

# ── LRU 查询缓存 ────────────────────────────────────────────────

_query_cache: dict[str, dict] = {}
MAX_CACHE = 128

def _cache_key(question: str) -> str:
    return question.strip().lower()

def cache_get(question: str) -> dict | None:
    return _query_cache.get(_cache_key(question))

def cache_set(question: str, result: dict) -> None:
    key = _cache_key(question)
    if len(_query_cache) >= MAX_CACHE:
        # evict oldest
        oldest = next(iter(_query_cache))
        del _query_cache[oldest]
    _query_cache[key] = result


# ── Entity Graph Retriever v2 ────────────────────────────────────

class EntityGraphRetriever:
    def __init__(self, index_path: Path):
        self.ready = False
        if not index_path.exists():
            return
        try:
            data = json.loads(index_path.read_text(encoding="utf-8"))
            self.type_index = data.get("type_index", {})
            self.prop_index = data.get("prop_index", {})
            self.rel_index  = data.get("rel_index",  {})
            self.ready      = True
        except Exception as e:
            console.print(f"[yellow]实体索引加载失败：{e}[/yellow]")

    def search(self, query: str, top_k: int = 10) -> list[dict]:
        if not self.ready:
            return []
        q = query.lower()
        scores: dict[str, float] = {}

        # Property value matching — v2: tokenise query for partial match
        q_tokens = set(re.split(r"\s+|[,，。；;:：]", q)) - {""}
        for key, eids in self.prop_index.items():
            _, val = key.split(":", 1) if ":" in key else ("", key)
            val_lower = val.lower()
            # Full match bonus
            if val_lower in q:
                for eid in eids:
                    scores[eid] = scores.get(eid, 0) + 3.0
            else:
                # Token partial match
                val_tokens = set(re.split(r"\s+|_", val_lower)) - {""}
                overlap = q_tokens & val_tokens
                if overlap:
                    for eid in eids:
                        scores[eid] = scores.get(eid, 0) + len(overlap) * 0.8

        # Entity ID direct match
        for eid in self.rel_index:
            if eid.lower() in q or any(t in eid.lower() for t in q_tokens if len(t) > 2):
                scores[eid] = scores.get(eid, 0) + 5.0

        # Type match
        for type_name, eids in self.type_index.items():
            if type_name.lower() in q:
                for eid in eids:
                    scores[eid] = scores.get(eid, 0) + 1.5

        ranked = sorted(scores.items(), key=lambda x: -x[1])[:top_k]
        return [
            {
                "entity_id": eid,
                "score":     score,
                "out_rels":  self.rel_index.get(eid, {}).get("out", [])[:5],
                "in_rels":   self.rel_index.get(eid, {}).get("in",  [])[:5],
                "source":    "entity_graph",
            }
            for eid, score in ranked
        ]


# ── SPARQL Retriever ─────────────────────────────────────────────

class SPARQLRetriever:
    def __init__(self, inferred_graph_path: Path, namespace: str):
        self.ready = False
        self.ns = namespace.rstrip("#") + "#"
        if not inferred_graph_path.exists():
            return
        try:
            from rdflib import Graph
            self.g = Graph()
            self.g.parse(str(inferred_graph_path), format="turtle")
            self.ready = True
        except Exception as e:
            console.print(f"[yellow]SPARQL 图加载失败：{e}[/yellow]")

    def query(self, sparql: str) -> list[dict]:
        if not self.ready:
            return []
        try:
            result = self.g.query(sparql)
            return [{str(k): str(v) for k, v in zip(result.vars, row)} for row in result]
        except Exception as e:
            return [{"error": str(e)}]

    def entity_search(self, query_text: str, top_k: int = 8) -> list[dict]:
        if not self.ready:
            return []
        from rdflib import Literal
        results: list[dict] = []
        q_lower = query_text.lower()
        q_tokens = set(q_lower.split()) - {""}

        for subj, pred, obj in self.g:
            if isinstance(obj, Literal):
                val = str(obj).lower()
                if q_lower in val or any(t in val for t in q_tokens if len(t) > 2):
                    local_s = str(subj).split("#")[-1].split("/")[-1]
                    local_p = str(pred).split("#")[-1].split("/")[-1]
                    results.append({
                        "entity_id":   local_s,
                        "matched_prop": local_p,
                        "matched_val": str(obj)[:200],
                        "score":       3.0,
                        "source":      "sparql",
                    })
                    if len(results) >= top_k * 3:
                        break

        seen: set[str] = set()
        unique = []
        for r in results:
            if r["entity_id"] not in seen:
                seen.add(r["entity_id"])
                unique.append(r)
        return unique[:top_k]


# ── Vector Retriever v2 (cosine distance) ───────────────────────

class VectorRetriever:
    def __init__(self, chroma_dir: Path, model_name: str):
        self.ready = False
        try:
            import chromadb
            from chromadb.utils import embedding_functions
            # v2 FIX: explicit cosine distance
            ef = embedding_functions.SentenceTransformerEmbeddingFunction(
                model_name=model_name
            )
            client = chromadb.PersistentClient(path=str(chroma_dir))
            # Get collections (created with cosine in 07_build_index v2)
            self.ent_col   = client.get_collection("kb_entities",  embedding_function=ef)
            self.chunk_col = client.get_collection("kb_chunks",    embedding_function=ef)
            self.ready = True
        except Exception as e:
            console.print(f"[yellow]向量检索不可用：{e}[/yellow]")

    def search(self, query: str, top_k: int = 8) -> list[dict]:
        if not self.ready:
            return []
        results: list[dict] = []
        for col, src in [(self.ent_col, "entity_vector"), (self.chunk_col, "chunk_vector")]:
            try:
                r = col.query(query_texts=[query], n_results=min(top_k, 10))
                for doc, meta, dist in zip(
                    r["documents"][0], r["metadatas"][0], r["distances"][0]
                ):
                    # cosine distance → similarity: 1 - distance
                    sim = max(0.0, 1.0 - dist)
                    results.append({"text": doc[:500], "meta": meta, "score": sim, "source": src})
            except Exception:
                pass
        return sorted(results, key=lambda x: -x["score"])[:top_k]


# ── BM25 Retriever ───────────────────────────────────────────────

class BM25Retriever:
    def __init__(self, index_path: Path):
        self.ready = False
        if not index_path.exists():
            return
        try:
            with open(index_path, "rb") as f:
                data = pickle.load(f)
            self.bm25         = data["bm25"]
            self.corpus_texts = data["corpus_texts"]
            self.corpus_metas = data["corpus_metas"]
            self.tokenizer    = data.get("tokenizer", "whitespace")
            self.ready        = True
        except Exception as e:
            console.print(f"[yellow]BM25 索引加载失败：{e}[/yellow]")

    def _tok(self, text: str) -> list[str]:
        if self.tokenizer == "jieba":
            try:
                import jieba
                return list(jieba.cut_for_search(text.lower()))
            except ImportError:
                pass
        return text.lower().split()

    def search(self, query: str, top_k: int = 8) -> list[dict]:
        if not self.ready:
            return []
        scores = self.bm25.get_scores(self._tok(query))
        top    = sorted(range(len(scores)), key=lambda i: -scores[i])[:top_k]
        return [
            {"text": self.corpus_texts[i][:500], "meta": self.corpus_metas[i],
             "score": float(scores[i]), "source": "bm25"}
            for i in top if scores[i] > 0
        ]


# ── RRF Fusion ───────────────────────────────────────────────────

def reciprocal_rank_fusion(
    result_lists: list[list[dict]],
    weights: list[float],
    k: int = 60,
) -> list[dict]:
    scores: dict[str, float] = {}
    items:  dict[str, dict]  = {}
    for lst, w in zip(result_lists, weights):
        for rank, item in enumerate(lst):
            key = item.get("entity_id") or item.get("text", "")[:80] or str(rank)
            scores[key] = scores.get(key, 0) + w / (k + rank + 1)
            if key not in items:
                items[key] = item
    return [
        {**items[k], "rrf_score": s}
        for k, s in sorted(scores.items(), key=lambda x: -x[1])
    ]


# ── Context Assembly ─────────────────────────────────────────────

def assemble_context(
    fused: list[dict],
    entity_graph_path: Path,
    top_k: int = 8,
) -> str:
    entity_lookup: dict[str, dict] = {}
    if entity_graph_path.exists():
        try:
            gd = json.loads(entity_graph_path.read_text(encoding="utf-8"))
            for ent in gd.get("entities", []):
                entity_lookup[ent["id"]] = ent
        except Exception:
            pass

    parts: list[str] = []
    seen:  set[str]  = set()

    for item in fused[:top_k]:
        src = item.get("source", "")
        if "entity" in src and "entity_id" in item:
            eid = item["entity_id"]
            if eid in seen:
                continue
            seen.add(eid)
            ent     = entity_lookup.get(eid, {})
            types   = ", ".join(ent.get("types", [eid]))
            props   = ent.get("properties", {})
            out_rels = item.get("out_rels", [])
            in_rels  = item.get("in_rels",  [])
            block  = f"【实体】{eid}（{types}）\n"
            if props:
                block += "  属性：\n" + "\n".join(
                    f"    {k}: {v}" for k, v in list(props.items())[:8]
                ) + "\n"
            if out_rels:
                block += "  关系（出）：" + "；".join(
                    f"{r['pred']}→{r['target']}" for r in out_rels[:4]
                ) + "\n"
            if in_rels:
                block += "  关系（入）：" + "；".join(
                    f"{r['source']}→{r['pred']}" for r in in_rels[:4]
                ) + "\n"
            parts.append(block)
        elif "text" in item:
            text = item["text"].strip()
            if not text or text[:40] in seen:
                continue
            seen.add(text[:40])
            src_file = item.get("meta", {}).get("source_file", "未知来源")
            parts.append(f"【文档｜{src_file}】\n{text}\n")

    return "\n---\n".join(parts) if parts else "（未找到相关内容）"


# ── LLM QA — Streaming v2 ────────────────────────────────────────

QA_SYSTEM = (
    "你是企业知识库智能助手。严格基于提供的知识上下文回答问题。\n"
    "规则：①只使用上下文信息 ②信息不足时明确说明 ③引用具体实体/文档来源 "
    "④多跳推理时逐步说明路径"
)

def ask_llm_streaming(
    question: str,
    context: str,
    history: list[dict],
    config: dict,
) -> str:
    """流式输出 LLM 回答，返回完整文本。"""
    provider = config.get("provider", "anthropic")
    model    = config.get("model",    "claude-sonnet-4-6")

    messages = list(history)
    messages.append({
        "role": "user",
        "content": (
            f"## 知识上下文\n{context}\n\n"
            f"## 问题\n{question}"
        ),
    })

    if provider == "anthropic":
        try:
            import anthropic
            api_key = os.environ.get(config.get("api_key_env","ANTHROPIC_API_KEY"))
            client  = anthropic.Anthropic(api_key=api_key)
            full_text = ""
            console.print("\n[bold green]回答[/bold green] ", end="")
            with client.messages.stream(
                model=model, max_tokens=2048,
                system=QA_SYSTEM,
                messages=messages,
            ) as stream:
                for chunk in stream.text_stream:
                    console.print(chunk, end="", highlight=False)
                    full_text += chunk
            console.print()  # newline after stream
            return full_text
        except Exception as e:
            return f"LLM 调用失败：{e}"

    elif provider == "openai":
        try:
            from openai import OpenAI
            api_key = os.environ.get(config.get("api_key_env","OPENAI_API_KEY"))
            client  = OpenAI(api_key=api_key)
            msgs    = [{"role":"system","content":QA_SYSTEM}] + messages
            full_text = ""
            console.print("\n[bold green]回答[/bold green] ", end="")
            for chunk in client.chat.completions.create(
                model=model, max_tokens=2048, stream=True, messages=msgs
            ):
                delta = chunk.choices[0].delta.content or ""
                console.print(delta, end="", highlight=False)
                full_text += delta
            console.print()
            return full_text
        except Exception as e:
            return f"LLM 调用失败：{e}"

    return "（LLM 不可用）"


# ── Query Engine v2 ───────────────────────────────────────────────

class KBQueryEngine:
    def __init__(self, project_dir: Path, config: dict):
        self.project_dir = project_dir
        self.config      = config
        idx_cfg  = config.get("index",   {})
        proj_cfg = config.get("project", {})
        ns       = proj_cfg.get("namespace","http://corp.example.com/ontology/kb#")

        chroma = Path(idx_cfg.get("chroma_persist_dir","./chroma_db"))
        if not chroma.is_absolute():
            chroma = project_dir / chroma
        embed  = idx_cfg.get("embedding_model","BAAI/bge-m3")

        index_dir = project_dir / "index"
        self.graph_path   = index_dir / "entities_graph.json"
        self.inferred_ttl = index_dir / "inferred_graph.ttl"

        self.sparql  = SPARQLRetriever(self.inferred_ttl, ns)
        self.vector  = VectorRetriever(chroma, embed)
        self.bm25    = BM25Retriever(index_dir / "bm25_index.pkl")
        self.entity  = EntityGraphRetriever(index_dir / "entity_index.json")
        self.llm_cfg = config.get("llm", {})

    def query(
        self,
        question: str,
        top_k: int = 8,
        custom_sparql: Optional[str] = None,
        history: Optional[list[dict]] = None,
        use_cache: bool = True,
        stream: bool = True,
    ) -> dict:
        # Cache check
        if use_cache and not custom_sparql:
            cached = cache_get(question)
            if cached:
                console.print("[dim]（缓存命中）[/dim]")
                return cached

        sparql_results = (
            [{"text": str(r), "source":"sparql","score":1.0} for r in self.sparql.query(custom_sparql)]
            if custom_sparql
            else self.sparql.entity_search(question, top_k)
        )
        vector_results = self.vector.search(question, top_k)
        bm25_results   = self.bm25.search(question, top_k)
        entity_results = self.entity.search(question, top_k)

        fused   = reciprocal_rank_fusion(
            [sparql_results, vector_results, bm25_results, entity_results],
            weights=[0.40, 0.30, 0.15, 0.15],
        )
        context = assemble_context(fused, self.graph_path, top_k)

        if stream:
            answer = ask_llm_streaming(question, context, history or [], self.llm_cfg)
        else:
            # Fallback non-streaming (for batch/API mode)
            answer = ask_llm_streaming(question, context, history or [], self.llm_cfg)

        result = {
            "question":      question,
            "answer":        answer,
            "context":       context,
            "sparql_hits":   len(sparql_results),
            "vector_hits":   len(vector_results),
            "bm25_hits":     len(bm25_results),
            "entity_hits":   len(entity_results),
            "fused_results": len(fused),
        }
        if use_cache:
            cache_set(question, result)
        return result

    def evaluate_cqs(self, cq_file: Path) -> dict:
        if not cq_file.exists():
            return {"error": "CQ 文件不存在"}
        text = cq_file.read_text(encoding="utf-8")
        cqs  = re.findall(r"- \[.\] (CQ-\d+:.+)", text)
        if not cqs:
            cqs = re.findall(r"[-*] (.+？|.+\?)", text)
        results = []
        answered = 0
        for cq in cqs[:20]:
            r = self.query(cq, top_k=5, stream=False, use_cache=False)
            ok = "未找到" not in r["answer"] and len(r["answer"]) > 20 and r["fused_results"] > 0
            answered += int(ok)
            results.append({"cq": cq, "answered": ok,
                            "answer_preview": r["answer"][:120], "hits": r["fused_results"]})
        coverage = round(answered / max(len(cqs), 1) * 100, 1)
        return {"total_cqs": len(cqs), "answered": answered,
                "coverage": f"{coverage}%", "details": results}


# ── CLI v2 — with history ─────────────────────────────────────────

HELP_TEXT = """
[bold cyan]命令帮助[/bold cyan]
  [yellow]/help[/yellow]   — 显示此帮助
  [yellow]/clear[/yellow]  — 清空对话历史
  [yellow]/eval[/yellow]   — 运行 CQ 覆盖率评估
  [yellow]/cache[/yellow]  — 显示缓存状态
  [yellow]/ctx[/yellow]    — 显示上一次检索上下文
  [yellow]sparql: SELECT ...[/yellow] — 直接执行 SPARQL 查询
  [yellow]exit / quit[/yellow] — 退出
"""

def run_cli(engine: KBQueryEngine):
    console.print(Panel(
        "[bold cyan]企业知识库问答系统 v2[/bold cyan]\n"
        "支持多轮对话 · 流式输出 · 结果缓存 · 输入 /help 查看命令",
        title="KB Query Interface",
    ))

    history: list[dict] = []
    last_context: str   = ""

    while True:
        try:
            question = console.input("\n[bold green]问题> [/bold green]").strip()
        except (EOFError, KeyboardInterrupt):
            break

        if not question:
            continue

        q_lower = question.lower()

        # ── 内置命令 ──
        if q_lower in ("exit", "quit", "q"):
            break
        if q_lower == "/help":
            console.print(Markdown(HELP_TEXT))
            continue
        if q_lower == "/clear":
            history.clear()
            console.print("[dim]对话历史已清空[/dim]")
            continue
        if q_lower == "/cache":
            console.print(f"[dim]缓存条目：{len(_query_cache)} / {MAX_CACHE}[/dim]")
            continue
        if q_lower == "/ctx":
            console.print(Panel(last_context or "（暂无）", title="上次检索上下文"))
            continue
        if q_lower == "/eval":
            console.print("[cyan]评估 CQ 覆盖率...[/cyan]")
            rpt = engine.evaluate_cqs(engine.project_dir / "competency_questions.md")
            console.print(f"覆盖率：[bold green]{rpt.get('coverage')}[/bold green]  "
                          f"({rpt.get('answered')}/{rpt.get('total_cqs')})")
            continue

        # ── SPARQL 直接执行 ──
        custom_sparql = None
        if question.lower().startswith("sparql:"):
            custom_sparql = question[7:].strip()
            question = f"SPARQL 查询：{custom_sparql}"

        # ── 检索 + 回答 ──
        result = engine.query(
            question,
            custom_sparql=custom_sparql,
            history=history,
            stream=True,
        )
        last_context = result["context"]

        # 追加到多轮历史
        history.append({"role": "user",      "content": question})
        history.append({"role": "assistant", "content": result["answer"]})
        if len(history) > 20:  # 保留最近 10 轮
            history = history[-20:]

        console.print(
            f"\n[dim]来源：SPARQL {result['sparql_hits']} | "
            f"向量 {result['vector_hits']} | "
            f"BM25 {result['bm25_hits']} | "
            f"实体图 {result['entity_hits']}[/dim]"
        )


# ── FastAPI v2 ────────────────────────────────────────────────────

def run_server(engine: KBQueryEngine, host: str = "0.0.0.0", port: int = 8765):
    try:
        from fastapi import FastAPI
        from fastapi.middleware.cors import CORSMiddleware
        from fastapi.responses import StreamingResponse
