    app = FastAPI(title="企业知识库 API v2", version="2.0.0")
    app.add_middleware(CORSMiddleware, allow_origins=["*"],
                      allow_methods=["*"], allow_headers=["*"])

    class QueryRequest(BaseModel):
        question:      str
        top_k:         int   = 8
        custom_sparql: Optional[str] = None
        use_cache:     bool  = True

    @app.post("/query")
    def query(req: QueryRequest):
        return engine.query(req.question, req.top_k, req.custom_sparql,
                            use_cache=req.use_cache, stream=False)

    @app.get("/evaluate")
    def evaluate():
        return engine.evaluate_cqs(engine.project_dir / "competency_questions.md")

    @app.get("/cache/clear")
    def clear_cache():
        _query_cache.clear()
        return {"cleared": True}

    @app.get("/health")
    def health():
        return {
            "status":       "ok",
            "sparql_ready": engine.sparql.ready,
            "vector_ready": engine.vector.ready,
            "bm25_ready":   engine.bm25.ready,
            "entity_ready": engine.entity.ready,
            "cache_size":   len(_query_cache),
        }

    console.print(f"[bold green]API 服务 v2：http://{host}:{port}[/bold green]")
    uvicorn.run(app, host=host, port=port)


# ── Main ──────────────────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(description="知识库查询接口 v2")
    ap.add_argument("--project-dir", "-p", default=".")
    ap.add_argument("--mode", choices=["cli","batch","serve"], default="cli")
    ap.add_argument("--host", default="0.0.0.0")
    ap.add_argument("--port", type=int, default=8765)
    ap.add_argument("--api-key", default=None)
    ap.add_argument("--no-cache", action="store_true", help="禁用查询缓存")
    args = ap.parse_args()

    if args.api_key:
        os.environ["ANTHROPIC_API_KEY"] = args.api_key

    project_dir = Path(args.project_dir)
    config = {}
    cfg    = project_dir / "kb_config.yaml"
    if cfg.exists():
        try:
            config = yaml.safe_load(cfg.read_text(encoding="utf-8"))
        except Exception:
            pass

    engine = KBQueryEngine(project_dir, config)

    if args.mode == "cli":
        run_cli(engine)
    elif args.mode == "serve":
        run_server(engine, args.host, args.port)
    elif args.mode == "batch":
        console.print("[cyan]批量 CQ 评估...[/cyan]")
        rpt = engine.evaluate_cqs(project_dir / "competency_questions.md")
        p   = project_dir / "reports" / "cq_evaluation.json"
        p.parent.mkdir(parents=True, exist_ok=True)
        p.write_text(json.dumps(rpt, ensure_ascii=False, indent=2), encoding="utf-8")
        console.print(f"覆盖率：[bold green]{rpt.get('coverage')}[/bold green]  报告：{p}")


if __name__ == "__main__":
    main()
