#!/usr/bin/env python3
"""
07_build_index.py — 混合索引构建 v2

v2 改进：
  - FIX: ChromaDB 集合使用 cosine 距离度量（明确设置）
  - NEW: 实体图索引增加 label 字段倒排
  - NEW: 增量追加模式（--mode append）
  - NEW: 索引健康检查（写入后验证 query 返回正常）
"""
import json, pickle, hashlib, argparse
from pathlib import Path
from datetime import datetime
import yaml
from rich.console import Console
from rich.progress import track
from rich.table import Table

console = Console()


def _fp(text: str) -> str:
    return hashlib.md5(text.encode()).hexdigest()[:12]


def load_config(d: Path) -> dict:
    p = d / "kb_config.yaml"
    if p.exists():
        try:
            return yaml.safe_load(p.read_text(encoding="utf-8"))
        except Exception:
            pass
    return {}


# ── ① Vector Index (ChromaDB — cosine) ─────────────────────────

def build_vector_index(
    project_dir: Path,
    graph_path: Path,
    parsed_dir: Path,
    chroma_dir: Path,
    model_name: str,
    mode: str = "replace",
) -> dict:
    try:
        import chromadb
        from chromadb.utils import embedding_functions
    except ImportError:
        console.print("[yellow]chromadb 未安装：pip install chromadb[/yellow]")
        return {}

    try:
        ef = embedding_functions.SentenceTransformerEmbeddingFunction(
            model_name=model_name
        )
    except Exception as e:
        console.print(f"[yellow]Embedding 模型加载失败：{e}[/yellow]")
        return {}

    client = chromadb.PersistentClient(path=str(chroma_dir))

    # v2 FIX: explicit cosine distance
    collection_meta = {"hnsw:space": "cosine"}

    if mode == "replace":
        for col_name in ("kb_entities", "kb_chunks"):
            try:
                client.delete_collection(col_name)
            except Exception:
                pass

    def _get_or_create(name: str):
        try:
            return client.get_collection(name, embedding_function=ef)
        except Exception:
            return client.create_collection(
                name,
                embedding_function=ef,
                metadata=collection_meta,
            )

    ent_col   = _get_or_create("kb_entities")
    chunk_col = _get_or_create("kb_chunks")

    entity_added = chunk_added = 0

    # Entity embeddings
    if graph_path.exists():
        try:
            gd       = json.loads(graph_path.read_text(encoding="utf-8"))
            entities = gd.get("entities", [])
            rels_map: dict[str, list[str]] = {e["id"]: [] for e in entities}
            for rel in gd.get("relations", []):
                sid = rel["subject"]
                if sid in rels_map:
                    rels_map[sid].append(f"{rel['predicate']}→{rel['object']}")

            batch_ids, batch_docs, batch_metas = [], [], []
            for ent in entities:
                eid   = ent["id"]
                types = ", ".join(ent.get("types", []))
                props = ent.get("properties", {})
                rels  = rels_map.get(eid, [])
                labels = " ".join(ent.get("labels", []))
                doc = (
                    f"[{types}] {eid} {labels}\n"
                    + "\n".join(f"  {k}: {v}" for k, v in props.items() if v)
                    + ("\n关系：" + "；".join(rels[:5]) if rels else "")
                )
                doc_id = f"ent_{_fp(eid)}"
                batch_ids.append(doc_id)
                batch_docs.append(doc[:2000])
                batch_metas.append({"entity_id": eid, "entity_type": types, "source": "entity"})

                if len(batch_ids) >= 64:
                    ent_col.add(ids=batch_ids, documents=batch_docs, metadatas=batch_metas)
                    entity_added += len(batch_ids)
                    batch_ids, batch_docs, batch_metas = [], [], []

            if batch_ids:
                ent_col.add(ids=batch_ids, documents=batch_docs, metadatas=batch_metas)
                entity_added += len(batch_ids)
        except Exception as e:
            console.print(f"[yellow]实体向量化失败：{e}[/yellow]")

    # Chunk embeddings
    if parsed_dir.exists():
        pfiles = list(parsed_dir.glob("*.json"))
        batch_ids, batch_docs, batch_metas = [], [], []
        for pf in track(pfiles, description="[cyan]向量化文本块...[/cyan]"):
            try:
                parsed = json.loads(pf.read_text(encoding="utf-8"))
            except Exception:
                continue
            fname = parsed.get("filename", "unknown")
            for idx, chunk in enumerate(parsed.get("chunks", [])):
                if not chunk.strip():
                    continue
                cid = f"chunk_{_fp(fname + str(idx))}"
                batch_ids.append(cid)
                batch_docs.append(chunk[:2000])
                batch_metas.append({"source_file": fname, "chunk_index": idx, "source": "chunk"})
                if len(batch_ids) >= 64:
                    chunk_col.add(ids=batch_ids, documents=batch_docs, metadatas=batch_metas)
                    chunk_added += len(batch_ids)
                    batch_ids, batch_docs, batch_metas = [], [], []
        if batch_ids:
            chunk_col.add(ids=batch_ids, documents=batch_docs, metadatas=batch_metas)
            chunk_added += len(batch_ids)

    # Health check
    try:
        if entity_added > 0:
            test = ent_col.query(query_texts=["test health check"], n_results=1)
            console.print(f"[green]向量索引健康检查 OK（实体集合 {ent_col.count()} 条）[/green]")
    except Exception as e:
        console.print(f"[yellow]向量索引健康检查失败：{e}[/yellow]")

    return {"entity_vectors": entity_added, "chunk_vectors": chunk_added,
            "total_vectors": entity_added + chunk_added}


# ── ② BM25 Index ────────────────────────────────────────────────

def build_bm25_index(project_dir: Path, graph_path: Path,
                     parsed_dir: Path, index_dir: Path) -> dict:
    try:
        from rank_bm25 import BM25Okapi
    except ImportError:
        console.print("[yellow]rank_bm25 未安装：pip install rank-bm25[/yellow]")
        return {}

    try:
        import jieba
        def tok(t: str) -> list[str]:
            return list(jieba.cut_for_search(t.lower()))
    except ImportError:
        def tok(t: str) -> list[str]:
            return t.lower().split()

    corpus_texts: list[str]  = []
    corpus_metas: list[dict] = []

    if graph_path.exists():
        try:
            gd = json.loads(graph_path.read_text(encoding="utf-8"))
            for ent in gd.get("entities", []):
                text = " ".join(
                    [ent["id"]]
                    + ent.get("labels", [])
                    + list(ent.get("properties", {}).values())
                )
                corpus_texts.append(text)
                corpus_metas.append({"source": "entity", "entity_id": ent["id"]})
        except Exception:
            pass

    if parsed_dir.exists():
        for pf in parsed_dir.glob("*.json"):
            try:
                parsed = json.loads(pf.read_text(encoding="utf-8"))
            except Exception:
                continue
            fname = parsed.get("filename", "unknown")
            for idx, chunk in enumerate(parsed.get("chunks", [])):
                if chunk.strip():
                    corpus_texts.append(chunk[:1500])
                    corpus_metas.append({"source": "chunk", "file": fname, "chunk_index": idx})

    if not corpus_texts:
        console.print("[yellow]BM25：无语料[/yellow]")
        return {}

    tokenized = [tok(t) for t in corpus_texts]
    bm25      = BM25Okapi(tokenized)
    index_dir.mkdir(parents=True, exist_ok=True)
    pkl = index_dir / "bm25_index.pkl"
    with open(pkl, "wb") as f:
        pickle.dump({
            "bm25": bm25, "corpus_texts": corpus_texts,
            "corpus_metas": corpus_metas,
            "tokenizer": "jieba" if "jieba" in str(tok) else "whitespace",
            "built_at": datetime.now().isoformat(timespec="seconds"),
        }, f)
    return {"bm25_docs": len(corpus_texts), "bm25_path": str(pkl)}


# ── ③ Entity Graph Index v2 (+ label倒排) ───────────────────────

def build_entity_index(graph_path: Path, index_dir: Path) -> dict:
    if not graph_path.exists():
        return {}
    try:
        gd = json.loads(graph_path.read_text(encoding="utf-8"))
    except Exception as e:
        console.print(f"[yellow]实体图读取失败：{e}[/yellow]")
        return {}

    entities  = gd.get("entities",  [])
    relations = gd.get("relations", [])

    type_index: dict[str, list[str]] = {}
    prop_index: dict[str, list[str]] = {}
    label_index:dict[str, list[str]] = {}   # v2 NEW
    rel_index:  dict[str, dict]      = {}

    for ent in entities:
        eid = ent["id"]
        for t in ent.get("types", []):
            type_index.setdefault(t, []).append(eid)
        for k, v in ent.get("properties", {}).items():
            key = f"{k}:{str(v).lower()[:50]}"
            prop_index.setdefault(key, []).append(eid)
        # v2: index labels
        for lbl in ent.get("labels", []):
            lkey = lbl.lower()[:80]
            label_index.setdefault(lkey, []).append(eid)
        rel_index[eid] = {"out": [], "in": []}

    for rel in relations:
        sid, oid, pred = rel["subject"], rel["object"], rel["predicate"]
        if sid in rel_index:
            rel_index[sid]["out"].append({"pred": pred, "target": oid})
        if oid in rel_index:
            rel_index[oid]["in"].append({"pred": pred, "source": sid})

    index_dir.mkdir(parents=True, exist_ok=True)
    idx_path = index_dir / "entity_index.json"
    idx_path.write_text(json.dumps({
        "built_at":     datetime.now().isoformat(timespec="seconds"),
        "entity_count": len(entities),
        "type_index":   type_index,
        "prop_index":   prop_index,
        "label_index":  label_index,
        "rel_index":    rel_index,
    }, ensure_ascii=False), encoding="utf-8")
    return {"entity_count": len(entities), "type_count": len(type_index),
            "prop_keys": len(prop_index), "label_keys": len(label_index)}


# ── Main ──────────────────────────────────────────────────────────

def main():
    ap = argparse.ArgumentParser(description="混合索引构建 v2")
    ap.add_argument("--project-dir", "-p", default=".")
    ap.add_argument("--mode", choices=["replace","append"], default="replace")
    ap.add_argument("--skip-vector", action="store_true")
    ap.add_argument("--skip-bm25",   action="store_true")
    args = ap.parse_args()

    project_dir = Path(args.project_dir)
    config      = load_config(project_dir)
    idx_cfg     = config.get("index", {})

    chroma = Path(idx_cfg.get("chroma_persist_dir", "./chroma_db"))
    if not chroma.is_absolute():
        chroma = project_dir / chroma
    embed  = idx_cfg.get("embedding_model", "BAAI/bge-m3")

    index_dir  = project_dir / "index"
    parsed_dir = project_dir / "extracted" / "parsed"
    graph_path = index_dir / "entities_graph.json"

    console.print("[bold cyan]构建混合检索索引 v2[/bold cyan]")
    stats: dict = {}

    if not args.skip_vector:
        console.print("\n[bold]① 向量索引（cosine）[/bold]")
        stats.update(build_vector_index(
            project_dir, graph_path, parsed_dir, chroma, embed, args.mode,
        ))
    if not args.skip_bm25 and idx_cfg.get("enable_bm25", True):
        console.print("\n[bold]② BM25[/bold]")
        stats.update(build_bm25_index(project_dir, graph_path, parsed_dir, index_dir))

    console.print("\n[bold]③ 实体图倒排索引 v2[/bold]")
    stats.update(build_entity_index(graph_path, index_dir))

    t = Table(title="索引汇总")
    t.add_column("类型", style="cyan"); t.add_column("统计", justify="right")
    for k, v in [
        ("向量-实体",   stats.get("entity_vectors","—")),
        ("向量-块",     stats.get("chunk_vectors","—")),
        ("BM25文档数",  stats.get("bm25_docs","—")),
        ("实体数",      stats.get("entity_count","—")),
        ("标签键数",    stats.get("label_keys","—")),
    ]:
        t.add_row(k, str(v))
    console.print(t)

    rpt = project_dir / "reports" / "index_report.json"
    rpt.parent.mkdir(parents=True, exist_ok=True)
    rpt.write_text(json.dumps({
        "built_at": datetime.now().isoformat(timespec="seconds"),
        "mode": args.mode, **{k: str(v) for k, v in stats.items()},
    }, ensure_ascii=False, indent=2), encoding="utf-8")

    st = project_dir / "state.yaml"
    if st.exists():
        try:
            state = yaml.safe_load(st.read_text(encoding="utf-8"))
            state["steps"]["07_index"] = "done"
            st.write_text(yaml.safe_dump(state, allow_unicode=True), encoding="utf-8")
        except Exception:
            pass

    console.print(f"\n✅ 索引完成  报告：[bold green]{rpt}[/bold green]")


if __name__ == "__main__":
    main()
